55	// Returns 'true' if 'l' is a better combined name than r.
56	bool CompareName(Node* l, Node* r) {
57	  if (l->HasAssignedName() && r->HasAssignedName()) {
58	    auto cmp = (l->GetNameView().size() <=> r->GetNameView().size());
59	    if (cmp == std::strong_ordering::equal) {
60	      return l->id() < r->id();
61	    } else {
62	      return cmp == std::strong_ordering::less;
63	    }
64	  }
65	  if (l->HasAssignedName()) {
66	    return true;
67	  }
68	  if (r->HasAssignedName()) {
69	    return false;
70	  }
71	  return l->id() < r->id();
72	}
