74	// Helper to represent a node that can be cse-d together.
75	class CseNode {
76	 public:
77	  CseNode(CseNode&&) = default;
78	  CseNode(const CseNode&) = default;
79	  CseNode& operator=(CseNode&&) = default;
80	  CseNode& operator=(const CseNode&) = default;
81	  CseNode(Op op, std::vector<CseNode*> operands,
82	          std::variant<int64_t, std::vector<uint8_t>> misc_data, Type* type)
83	      : op_(op),
84	        operands_(std::move(operands)),
85	        misc_data_(std::move(misc_data)),
86	        type_(type),
87	        id_(-1) {}
88	  CseNode(Node* n, std::vector<CseNode*> operands,
89	          std::variant<int64_t, std::vector<uint8_t>> misc_data)
90	      : CseNode(n->op(), std::move(operands), std::move(misc_data),
91	                n->GetType()) {}
92	
93	  bool is_forced_unique() const {
94	    return std::holds_alternative<int64_t>(misc_data_);
95	  }
96	  // 'id' isn't used for equivalence and only used to provide a consistent order
97	  // for operands which are commutative.
98	  int64_t id() const { return id_; }
99	  void set_id(int64_t id) { id_ = id; }
100	
101	  // Equality operator for use in hash maps.
102	  bool operator==(const CseNode& other) const {
103	    if (op_ != other.op_) {
104	      return false;
105	    }
106	    if (misc_data_ != other.misc_data_) {
107	      return false;
108	    }
109	    if (type_ != other.type_) {
110	      return false;
111	    }
112	    if (operands_.size() != other.operands_.size()) {
113	      return false;
114	    }
115	    // NB No need to deref since the pointers are canonical.
116	    for (size_t i = 0; i < operands_.size(); ++i) {
117	      if (operands_[i] != other.operands_[i]) {
118	        return false;
119	      }
120	    }
121	    return true;
122	  }
123	
124	  // Required for absl::Hash.
125	  template <typename H>
126	  friend H AbslHashValue(H h, const CseNode& c) {
127	    h = H::combine(std::move(h), c.op_, c.misc_data_, c.type_);
128	    for (const CseNode* operand : c.operands_) {
129	      h = H::combine(std::move(h), operand);
130	    }
131	    return h;
132	  }
133	
134	 private:
135	  Op op_;
136	  std::vector<CseNode*> operands_;
137	  // Some operations have config that isn't embedded in the (op, operands,
138	  // result-ty) tuple (eg the start bit of a bitslice, the exact element of a
139	  // tuple-index etc). These are needed to identify which values can be
140	  // combined. We simply serialize the data to the vector here and use it ensure
141	  // comparison works. Since we don't actually care about what the data says we
142	  // don't do any sort of padding.
143	  //
144	  // NB A bunch of operations do include extra data that is duplicitive of the
145	  // result type. We don't bother to include that here (though we could without
146	  // issue).
147	  //
148	  // For some nodes which should never be combined we just put a unique number
149	  // in this field to ensure the CseNode evaluates not-equal to every other
150	  // CseNode.
151	  std::variant<int64_t, std::vector<uint8_t>> misc_data_;
152	  Type* type_;
153	  // id used for sorting only. Not considered part of the struct for hash or eq.
154	  int64_t id_;
155	};
156	class CseNodeArena {
157	 public:
158	  explicit CseNodeArena(bool common_literals, FunctionBase* f)
159	      : common_literals_(common_literals) {
160	    node_map_.reserve(f->node_count());
161	    nodes_.reserve(f->node_count());
162	    arena_.reserve(f->node_count());
163	  }
164	  absl::StatusOr<CseNode*> GetOrCreate(Node* n) {
165	    if (auto it = node_map_.find(n); it != node_map_.end()) {
166	      return it->second;
167	    }
168	    XLS_ASSIGN_OR_RETURN(std::unique_ptr<CseNode> node, Create(n));
169	    // Make sure that side-effecting ops (other than gate) are marked as
170	    // force-unique.
171	    XLS_RET_CHECK(!OpIsSideEffecting(n->op()) || n->op() == Op::kGate ||
172	                  node->is_forced_unique())
173	        << n << " is not forced unique while side-effecting";
174	    auto it = nodes_.find(CseNodeHolder{node.get()});
175	    if (it != nodes_.end()) {
176	      node_map_[n] = it->get();
177	      return it->get();
178	    }
179	    node_map_[n] = node.get();
180	    node->set_id(next_id_++);
181	    nodes_.emplace(node.get());
182	    CseNode* res = node.get();
183	    arena_.push_back(std::move(node));
184	    return res;
185	  }
186	  absl::StatusOr<CseNode*> Get(Node* n) {
187	    auto it = node_map_.find(n);
188	    if (it == node_map_.end()) {
189	      return absl::NotFoundError(
190	          absl::StrFormat("Node %s not found in CSE node arena", n->GetName()));
191	    }
192	    return it->second;
193	  }
194	
195	 private:
196	  absl::StatusOr<std::unique_ptr<CseNode>> Create(Node* n) {
197	    std::vector<CseNode*> operands;
198	    operands.reserve(n->operands().size());
199	    for (Node* operand : n->operands()) {
200	      // Built in TopoSort order so the operands should have already been
201	      // created.
202	      XLS_ASSIGN_OR_RETURN(
203	          std::back_inserter(operands), Get(operand),
204	          _ << "Unable to cse " << n << " due to operand being unvisited");
205	    }
206	    if (OpIsCommutative(n->op())) {
207	      absl::c_sort(operands,
208	                   [](CseNode* a, CseNode* b) { return a->id() < b->id(); });
209	    }
210	    auto bytes_data = [](int64_t v) {
211	      std::vector<uint8_t> data;
212	      data.reserve(8);
213	      std::array<uint8_t, 8> arr = std::bit_cast<std::array<uint8_t, 8>>(v);
214	      data.insert(data.end(), arr.begin(), arr.end());
215	      return data;
216	    };
217	    auto add_bytes = [](std::vector<uint8_t>& data, int64_t v) {
218	      std::array<uint8_t, 8> arr = std::bit_cast<std::array<uint8_t, 8>>(v);
219	      data.insert(data.end(), arr.begin(), arr.end());
220	    };
221	    // Add in any extra data that is can distinguish one node of a particular
222	    // type, operation and operands with another.
223	    switch (n->op()) {
224	      // assumed_in_bounds_
225	      case Op::kArrayIndex: {
226	        return std::make_unique<CseNode>(
227	            n, std::move(operands),
228	            std::vector<uint8_t>{n->As<ArrayIndex>()->assumed_in_bounds()});
229	      }
230	      // assumed_in_bounds_
231	      case Op::kArrayUpdate: {
232	        return std::make_unique<CseNode>(
233	            n, std::move(operands),
234	            std::vector<uint8_t>{n->As<ArrayUpdate>()->assumed_in_bounds()});
235	      }
236	      // start
237	      case Op::kBitSlice: {
238	        return std::make_unique<CseNode>(
239	            n, std::move(operands), bytes_data(n->As<BitSlice>()->start()));
240	      }
241	      // priority
242	      case Op::kOneHot: {
243	        return std::make_unique<CseNode>(
244	            n, std::move(operands),
245	            std::vector<uint8_t>{n->As<OneHot>()->priority() == LsbOrMsb::kLsb
246	                                     ? uint8_t{1}
247	                                     : uint8_t{0}});
248	      }
249	      // index
250	      case Op::kTupleIndex: {
251	        return std::make_unique<CseNode>(
252	            n, std::move(operands), bytes_data(n->As<TupleIndex>()->index()));
253	      }
254	      // trip-count, stride, body-function
255	      case Op::kCountedFor: {
256	        std::vector<uint8_t> data;
257	        add_bytes(data, n->As<CountedFor>()->trip_count());
258	        add_bytes(data, n->As<CountedFor>()->stride());
259	        add_bytes(data, static_cast<int64_t>(std::bit_cast<intptr_t>(
260	                            n->As<CountedFor>()->body())));
261	        return std::make_unique<CseNode>(n, std::move(operands),
262	                                         std::move(data));
263	      }
264	      // function
265	      case Op::kDynamicCountedFor: {
266	        return std::make_unique<CseNode>(
267	            n, std::move(operands),
268	            bytes_data(static_cast<int64_t>(
269	                std::bit_cast<intptr_t>(n->As<DynamicCountedFor>()->body()))));
270	      }
271	      // function
272	      case Op::kInvoke: {
273	        return std::make_unique<CseNode>(
274	            n, std::move(operands),
275	            bytes_data(static_cast<int64_t>(
276	                std::bit_cast<intptr_t>(n->As<Invoke>()->to_apply()))));
277	      }
278	      // function
279	      case Op::kMap: {
280	        return std::make_unique<CseNode>(
281	            n, std::move(operands),
282	            bytes_data(static_cast<int64_t>(
283	                std::bit_cast<intptr_t>(n->As<Map>()->to_apply()))));
284	      }
285	      // The actual literal value (or 'do not cse' if !common_literals_)
286	      case Op::kLiteral: {
287	        if (common_literals_) {
288	          // Flatten data. Just use the proto format.
289	          std::vector<uint8_t> data;
290	          XLS_ASSIGN_OR_RETURN(auto proto, n->As<Literal>()->value().AsProto());
291	          data.resize(proto.ByteSizeLong());
292	          XLS_RET_CHECK(proto.SerializeToArray(data.data(), data.size()))
293	              << "Failed to serialize literal for " << n;
294	          return std::make_unique<CseNode>(n, std::move(operands),
295	                                           std::move(data));
296	        }
297	        // We don't want to merge literals so just make each of them unique.
298	        return std::make_unique<CseNode>(n, std::move(operands), non_cse_id_++);
299	      }
300	      // do not cse. All of these should never be merged since they are
301	      // side-effecting.
302	      case Op::kAssert:
303	      case Op::kCover:
304	      case Op::kInputPort:
305	      case Op::kInstantiationInput:
306	      case Op::kInstantiationOutput:
307	      case Op::kMinDelay:
308	      case Op::kNewChannel:
309	      case Op::kNext:
310	      case Op::kOutputPort:
311	      case Op::kParam:
312	      case Op::kReceive:
313	      case Op::kRecvChannelEnd:
314	      case Op::kRegisterRead:
315	      case Op::kRegisterWrite:
316	      case Op::kSend:
317	      case Op::kSendChannelEnd:
318	      case Op::kStateRead:
319	      case Op::kTrace: {
320	        return std::make_unique<CseNode>(n, std::move(operands), non_cse_id_++);
321	      }
322	      // everything below here does not need any additional information.
323	      case Op::kAdd:
324	      case Op::kAfterAll:
325	      case Op::kAnd:
326	      case Op::kAndReduce:
327	      case Op::kArray:
328	      case Op::kArrayConcat:
329	      case Op::kArraySlice:
330	      case Op::kBitSliceUpdate:
331	      case Op::kConcat:
332	      case Op::kDecode:
333	      case Op::kDynamicBitSlice:
334	      case Op::kEncode:
335	      case Op::kEq:
336	      case Op::kGate:
337	      case Op::kIdentity:
338	      case Op::kNand:
339	      case Op::kNe:
340	      case Op::kNeg:
341	      case Op::kNor:
342	      case Op::kNot:
343	      case Op::kOneHotSel:
344	      case Op::kOr:
345	      case Op::kOrReduce:
346	      case Op::kPrioritySel:
347	      case Op::kReverse:
348	      case Op::kSDiv:
349	      case Op::kSGe:
350	      case Op::kSGt:
351	      case Op::kSLe:
352	      case Op::kSLt:
353	      case Op::kSMod:
354	      case Op::kSMul:
355	      case Op::kSMulp:
356	      case Op::kSel:
357	      case Op::kShll:
358	      case Op::kShra:
359	      case Op::kShrl:
360	      case Op::kSignExt:
361	      case Op::kSub:
362	      case Op::kTuple:
363	      case Op::kUDiv:
364	      case Op::kUGe:
365	      case Op::kUGt:
366	      case Op::kULe:
367	      case Op::kULt:
368	      case Op::kUMod:
369	      case Op::kUMul:
370	      case Op::kUMulp:
371	      case Op::kXor:
372	      case Op::kXorReduce:
373	      case Op::kZeroExt: {
374	        return std::make_unique<CseNode>(n, std::move(operands),
375	                                         std::vector<uint8_t>{});
376	      }
377	    }
378	  }
379	  struct CseNodeHolder {
380	    CseNode* node_;
381	
382	    CseNode* get() const { return node_; }
383	    template <typename H>
384	    friend H AbslHashValue(H h, const CseNodeHolder& c) {
385	      return AbslHashValue(std::move(h), *c.node_);
386	    }
387	    bool operator==(const CseNodeHolder& other) const {
388	      return *node_ == *other.node_;
389	    }
390	  };
391	
392	  bool common_literals_;
393	  // Id used for sorting commutative operations based on the order they are
394	  // encountered.
395	  int64_t next_id_ = 1;
396	  // Id used to ensure that all non-cse-eligible nodes are considered globally
397	  // unique. Has no semantic meaning.
398	  int64_t non_cse_id_ = 1;
399	  absl::flat_hash_map<Node*, CseNode*> node_map_;
400	  absl::flat_hash_set<CseNodeHolder> nodes_;
401	  std::vector<std::unique_ptr<CseNode>> arena_;
402	};
403	
404	}  // namespace
405	
406	absl::StatusOr<bool> RunCse(FunctionBase* f, OptimizationContext& context,
407	                            absl::flat_hash_map<Node*, Node*>* replacements,
408	                            bool common_literals) {
409	  CseNodeArena arena(common_literals, f);
410	  // All the nodes in an equivalence set that we've found so far.
411	  absl::flat_hash_map<CseNode*, std::vector<Node*>> node_buckets;
412	
413	  int64_t dead_nodes = 0;
414	  node_buckets.reserve(f->node_count());
415	  // Identify all the equivalence groups.
416	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> topo_sort_nodes, context.TopoSort(f));
417	  for (Node* node : topo_sort_nodes) {
418	    // Normally, dead nodes are removed by the DCE pass. However, if the node is
419	    // (e.g.) an invoke, DCE won't touch it, waiting for inlining to remove
420	    // it... and if we try to replace it, we'll think we changed the IR when we
421	    // actually didn't.
422	    if (node->IsDead()) {
423	      ++dead_nodes;
424	      continue;
425	    }
426	    // NB arena determines what nodes are eligible for cse.
427	    XLS_ASSIGN_OR_RETURN(CseNode * cse, arena.GetOrCreate(node));
428	    node_buckets[cse].push_back(node);
429	  }
430	
431	  // Short circuit. Pigeonhole principle. All groups must have only a single
432	  // element.
433	  if (node_buckets.size() + dead_nodes == f->node_count()) {
434	    return false;
435	  }
436	  // Actually do the replacement.
437	  for (const auto& [_, bucket] : node_buckets) {
438	    if (bucket.size() == 1) {
439	      continue;
440	    }
441	    CHECK(!bucket.empty()) << "How did an empty bucket end up here?";
442	    // Pick the shortest name. This ensures that we deterministically
443	    // choose the "canonical" node in case there are multiple options.
444	    Node* representative = *absl::c_min_element(bucket, CompareName);
445	    for (Node* node : bucket) {
446	      if (node != representative) {
447	        if (replacements != nullptr) {
448	          replacements->insert({node, representative});
449	        }
450	        VLOG(3) << absl::StreamFormat("Replacing %s with equivalent node %s",
451	                                      node->GetName(),
452	                                      representative->GetName());
453	
454	        // TODO(allight): Merge the location information too.
455	        XLS_RETURN_IF_ERROR(node->ReplaceUsesWith(representative));
456	      }
457	    }
458	  }
459	
460	  return true;
461	}
462	
463	RedundancyGuard CsePass::GetRedundancyGuard(
464	    const OptimizationPassOptions& options,
465	    OptimizationContext& context) const {
466	  return RedundancyGuard::CanSkip(common_literals_ ? "literals"
467	                                                   : "no_literals");
468	}
469	
470	absl::StatusOr<bool> CsePass::RunOnFunctionBaseInternal(
471	    FunctionBase* f, const OptimizationPassOptions& options,
472	    PassResults* results, OptimizationContext& context) const {
473	  return RunCse(f, context, nullptr, common_literals_);
474	}
475	
476	}  // namespace xls
