35	absl::StatusOr<bool> DeadCodeEliminationPass::RunOnFunctionBaseInternal(
36	    FunctionBase* f, const OptimizationPassOptions& options,
37	    PassResults* results, OptimizationContext& context) const {
38	  auto is_deletable = [](Node* n) {
39	    // Don't remove invokes, they will be removed by inlining. The invoked
40	    // functions could have side effects, so DCE shouldn't remove them.
41	    //
42	    // TODO: google/xls#1806 -  consider making invokes side-effecting if we can
43	    // deal with FFI well.
44	    return !n->function_base()->HasImplicitUse(n) && !n->Is<Invoke>() &&
45	           (!OpIsSideEffecting(n->op()) || n->Is<Gate>());
46	  };
47	
48	  std::deque<Node*> worklist;
49	  for (Node* n : f->nodes()) {
50	    if (n->users().empty() && is_deletable(n)) {
51	      worklist.push_back(n);
52	    }
53	  }
54	  int64_t removed_count = 0;
55	  absl::flat_hash_set<Node*> unique_operands_scratch;
56	  while (!worklist.empty()) {
57	    Node* node = worklist.front();
58	    worklist.pop_front();
59	
60	    // A node may appear more than once as an operand of 'node'. Keep track of
61	    // which operands have been handled.
62	    ForEachUnique(
63	        node->operands(),
64	        [&](Node* operand) {
65	          if (HasSingleUse(operand) && is_deletable(operand)) {
66	            worklist.push_back(operand);
67	          }
68	        },
69	        /*scratch_set=*/unique_operands_scratch);
70	    VLOG(3) << "DCE removing " << node->ToString();
71	    XLS_RETURN_IF_ERROR(f->RemoveNode(node));
72	    removed_count++;
73	  }
74	
75	  VLOG(2) << "Removed " << removed_count << " dead nodes";
76	  // Use this pass to clean up context once we've removed nodes.
77	  if (removed_count > 0) {
78	    XLS_RETURN_IF_ERROR(context.CollectGarbage());
79	  }
80	  return removed_count > 0;
81	}
82	
83	}  // namespace xls
