39	// Check if we can do constant folding on this node.
40	bool NodeIsConstantFoldable(Node* node, QueryEngine& query_engine) {
41	  if (node->users().empty() && !node->function_base()->HasImplicitUse(node)) {
42	    // If the node has no users, replacing it with a literal is pointless.
43	    return false;
44	  }
45	  if (node->Is<Literal>()) {
46	    // Already a constant, nothing to do.
47	    return false;
48	  }
49	  if (TypeHasToken(node->GetType())) {
50	    // Tokens can't be folded.
51	    return false;
52	  }
53	  if (OpIsSideEffecting(node->op()) && !node->Is<Gate>()) {
54	    // Side effecting ops other than 'gate' can't be folded through.
55	    return false;
56	  }
57	  // Only ops with all literal operands can be folded.
58	  return absl::c_all_of(node->operands(), [&](Node* operand) {
59	    return query_engine.IsFullyKnown(operand);
60	  });
61	}
