65	absl::StatusOr<bool> ConstantFoldingPass::RunOnFunctionBaseInternal(
66	    FunctionBase* f, const OptimizationPassOptions& options,
67	    PassResults* results, OptimizationContext& context) const {
68	  StatelessQueryEngine query_engine;
69	
70	  bool changed = false;
71	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> topo_sort_nodes, context.TopoSort(f));
72	  for (Node* node : topo_sort_nodes) {
73	    // Fold any non-side-effecting op with constant parameters. Avoid any types
74	    // with tokens because literal tokens are not allowed.
75	    // TODO(meheff): 2019/6/26 Consider not folding loops with large trip counts
76	    // to avoid hanging at compile time.
77	    if (NodeIsConstantFoldable(node, query_engine)) {
78	      VLOG(2) << "Folding: " << *node;
79	      std::vector<Value> operand_values;
80	      for (Node* operand : node->operands()) {
81	        operand_values.push_back(*query_engine.KnownValue(operand));
82	      }
83	      XLS_ASSIGN_OR_RETURN(Value result, InterpretNode(node, operand_values));
84	      XLS_RETURN_IF_ERROR(node->ReplaceUsesWithNew<Literal>(result).status());
85	      changed = true;
86	    }
87	  }
88	
89	  return changed;
90	}
