49	namespace {
50	
51	// Return the name that 'node' should have when it is inlined at the callsite
52	// given by 'invoke'. The node must be in the function called by 'invoke'. The
53	// name is generated by first determining if the name of 'node' is likely
54	// derived from the parameter name of its function. If so, a new name is
55	// generated using the respective operand name of 'invoke' substituted for the
56	// parameter name. If no meaningful name could be determined then nullopt is
57	// returned.
58	std::optional<std::string> GetInlinedNodeName(Node* node, Invoke* invoke) {
59	  if (!node->HasAssignedName()) {
60	    return std::nullopt;
61	  }
62	
63	  // Find the parameter in the invoked function whose name is a prefix of the
64	  // name of 'node'. If such a parameter exists we assume the name of 'node' is
65	  // derived from the name of this param. If there are multiple matches, then
66	  // choose the param with the longest name (e.g., if the node's name is
67	  // 'foo_bar_42' and there are parameters named 'foo' and 'foo_bar' we assume
68	  // 'foo_bar_42' is derived from 'foo_bar').
69	  Param* matching_param = nullptr;
70	  std::string derived_name;
71	  for (int64_t i = 0; i < invoke->operand_count(); ++i) {
72	    Param* param = invoke->to_apply()->param(i);
73	    Node* operand = invoke->operand(i);
74	    if (operand->HasAssignedName() &&
75	        absl::StartsWith(node->GetName(), param->GetName()) &&
76	        (matching_param == nullptr ||
77	         matching_param->GetName().size() < param->GetName().size())) {
78	      matching_param = param;
79	      std::string suffix = node->GetName().substr(param->GetName().size());
80	      derived_name = NodeNameConcat(operand, suffix);
81	    }
82	  }
83	  if (matching_param == nullptr) {
84	    return std::nullopt;
85	  }
86	  return derived_name;
87	}
88	
89	// Inlining can cause coverpoints to be duplicated, which will then conflict, as
90	// a Verilog cover property must have a unique name. To handle this, we prepend
91	// the original node ID to an inlined coverpoint. Post-processing will be needed
92	// to re-aggregate coverpoints disaggregated in this method.
93	std::string GetPrefixedLabel(Invoke* invoke, std::string_view label,
94	                             int inline_count) {
95	  FunctionBase* caller = invoke->function_base();
96	  return absl::StrCat(caller->name(), "_", inline_count, "_",
97	                      invoke->to_apply()->name(), "_", label);
98	}
99	
100	static bool IsInlineable(const Invoke* invoke) {
101	  // Foreign functions can not and should not be inlined.
102	  return !invoke->to_apply()->ForeignFunctionData().has_value();
103	}
104	
105	// Inlines the node "invoke" by replacing it with the contents of the called
106	// function.
107	template <bool kCheckNoSubInvokes = true>
108	absl::Status InlineInvoke(Invoke* invoke, OptimizationContext& context,
109	                          int inline_count) {
110	  Function* invoked = invoke->to_apply();
111	  absl::flat_hash_map<Node*, Node*> invoked_node_to_replacement;
112	  for (int64_t i = 0; i < invoked->params().size(); ++i) {
113	    Node* param = invoked->param(i);
114	    invoked_node_to_replacement[param] = invoke->operand(i);
115	  }
116	
117	  XLS_ASSIGN_OR_RETURN(std::vector<Node*> topo_sort_nodes,
118	                       context.TopoSort(invoked));
119	  for (Node* node : topo_sort_nodes) {
120	    if (invoked_node_to_replacement.contains(node)) {
121	      // Already taken care of (e.g. parameters above).
122	      continue;
123	    }
124	    XLS_RET_CHECK(!kCheckNoSubInvokes ||
125	                  // All invokes before us should've been inlined (except ffi)
126	                  !node->Is<Invoke>() || !IsInlineable(node->As<Invoke>()))
127	        << "No invokes that are not FFI should remain in function to inline: "
128	        << node->GetName() << ": " << node->As<Invoke>()->to_apply()->name();
129	    std::vector<Node*> new_operands;
130	    for (Node* operand : node->operands()) {
131	      new_operands.push_back(invoked_node_to_replacement.at(operand));
132	    }
133	    XLS_ASSIGN_OR_RETURN(
134	        Node * new_node,
135	        node->CloneInNewFunction(new_operands, invoke->function_base()));
136	    if (new_node->loc().Empty()) {
137	      new_node->SetLoc(invoke->loc());
138	    } else {
139	      std::vector<SourceLocation> locs(new_node->loc().locations);
140	      locs.reserve(new_node->loc().locations.size() +
141	                   invoke->loc().locations.size());
142	      absl::c_copy(invoke->loc().locations, std::back_inserter(locs));
143	      new_node->SetLoc(SourceInfo(std::move(locs)));
144	    }
145	    invoked_node_to_replacement[node] = new_node;
146	  }
147	
148	  // Update names for each of the newly inlined nodes. For example,
149	  // if the callsite looks like:
150	  //
151	  //   invoke.1: invoke(foo, to_apply=f)
152	  //
153	  // and the function is:
154	  //
155	  //   fn f(x: bits[32]) -> bits[32] {
156	  //     ...
157	  //     x_negated: bits[32] = neg(x)
158	  //     ...
159	  //   }
160	  //
161	  // Then 'x_negated' when inlined at the invoke callsite will have the name
162	  // 'foo_negated'. Coverpoint and assert names are also updated to include the
163	  // call stack to differentiate in case inlining would otherwise result in
164	  // multiple statements with the same labels.
165	  for (Node* node : invoked->nodes()) {
166	    if (node->Is<Param>()) {
167	      continue;
168	    }
169	    if (node == invoked->return_value() && invoke->HasAssignedName()) {
170	      // Node is the return value of the function, it should get its name from
171	      // the invoke node itself. By clearing the name here ReplaceUseWith will
172	      // properly move the name from the invoke instruction to the node.
173	      invoked_node_to_replacement.at(node)->ClearName();
174	      continue;
175	    }
176	    std::optional<std::string> new_name = GetInlinedNodeName(node, invoke);
177	    if (new_name.has_value()) {
178	      invoked_node_to_replacement.at(node)->SetName(new_name.value());
179	    }
180	
181	    if (node->Is<Cover>()) {
182	      Cover* c = node->As<Cover>();
183	      std::string original_label = c->original_label().value_or(c->label());
184	      std::string new_label =
185	          GetPrefixedLabel(invoke, node->As<Cover>()->label(), inline_count);
186	      Cover* cover = invoked_node_to_replacement.at(node)->As<Cover>();
187	      Node* condition = cover->condition();
188	      XLS_ASSIGN_OR_RETURN(auto new_cover,
189	                           cover->function_base()->MakeNodeWithName<Cover>(
190	                               cover->loc(), condition, new_label,
191	                               std::move(original_label), cover->GetName()));
192	      XLS_RETURN_IF_ERROR(cover->ReplaceUsesWith(new_cover));
193	      XLS_RETURN_IF_ERROR(cover->function_base()->RemoveNode(cover));
194	      invoked_node_to_replacement.at(node) = new_cover;
195	    } else if (node->Is<Assert>() && node->As<Assert>()->label().has_value()) {
196	      Assert* a = node->As<Assert>();
197	      std::optional<std::string> original_label =
198	          a->original_label().has_value() ? a->original_label() : a->label();
199	      std::string new_label = GetPrefixedLabel(
200	          invoke, node->As<Assert>()->label().value(), inline_count);
201	      Assert* asrt = invoked_node_to_replacement.at(node)->As<Assert>();
202	      Node* token = asrt->token();
203	      Node* condition = asrt->condition();
204	      XLS_ASSIGN_OR_RETURN(auto new_assert,
205	                           asrt->function_base()->MakeNodeWithName<Assert>(
206	                               asrt->loc(), token, condition, asrt->message(),
207	                               new_label, original_label, asrt->GetName()));
208	      XLS_RETURN_IF_ERROR(asrt->ReplaceUsesWith(new_assert));
209	      XLS_RETURN_IF_ERROR(asrt->function_base()->RemoveNode(asrt));
210	      invoked_node_to_replacement.at(node) = new_assert;
211	    }
212	  }
213	
214	  XLS_RETURN_IF_ERROR(invoke->ReplaceUsesWith(
215	      invoked_node_to_replacement.at(invoked->return_value())));
216	  return invoke->function_base()->RemoveNode(invoke);
217	}
218	
219	std::vector<FunctionBase*> GetFunctionsToInlineByLeaf(Package* p,
220	                                                      const CallGraph& cg) {
221	  std::vector<FunctionBase*> functions = FunctionsInPostOrder(p);
222	  std::vector<FunctionBase*> functions_to_inline;
223	  functions_to_inline.reserve(functions.size());
224	  absl::flat_hash_set<FunctionBase*> to_inline_set;
225	  to_inline_set.reserve(functions.size());
226	  for (FunctionBase* f : functions) {
227	    if (cg.FunctionsCalledBy(f).empty()) {
228	      // No invokes at all.
229	      continue;
230	    }
231	    // Inline function if all of the functions it calls are either leafs or
232	    // the single call of a non-leaf which transitively only calls leafs.
233	    if (absl::c_all_of(cg.FunctionsCalledBy(f), [&](Node* n) {
234	          CHECK(n->Is<Invoke>()) << "all maps and for-loops must be cleared "
235	                                    "before inlining. Found: "
236	                                 << n;
237	          Invoke* called = n->As<Invoke>();
238	          int64_t to_inline_cnt = absl::c_count_if(
239	              cg.FunctionsCalledBy(called->to_apply()), [](Node* n) {
240	                CHECK(n->Is<Invoke>()) << "all maps and for-loops must be "
241	                                          "cleared before inlining. Found: "
242	                                       << n;
243	                // Need to avoid counting FFI functions.
244	                return IsInlineable(n->As<Invoke>());
245	              });
246	          // Also inline the invoke if the callee is only called by the invoke
247	          // and the callee is also being inlined.
248	          return to_inline_cnt == 0 ||
249	                 (to_inline_cnt == 1 &&
250	                  to_inline_set.contains(called->to_apply()));
251	        })) {
252	      functions_to_inline.push_back(f);
253	      to_inline_set.insert(f);
254	    }
255	  }
256	  return functions_to_inline;
257	}
258	
259	}  // namespace
260	
261	absl::Status InliningPass::InlineOneInvoke(Invoke* invoke) {
262	  OptimizationContext context;
263	  return InlineInvoke</*kCheckNoSubInvokes=*/false>(invoke, context,
264	                                                    /*inline_count=*/0);
265	}
266	
