57	// The largest size of lookup table we will use when transforming a division
58	// into a pure (uncompressed) lookup table. This is not backed by any particular
59	// data, but seems a reasonable size limit for a LUT.
60	constexpr int64_t kMaxConstantDividendLUTSize = 64;
61	
62	// The largest constant dividend K for which we will transform a division K/x
63	// into a lookup table. The priority-select portion of the lookup table has size
64	// up to approximately sqrt(K). This is not backed by any particular data, but
65	// lets us handle division by reasonably large dividends without excessively
66	// large LUT logic.
67	//
68	// TODO(epastor): Maybe replace with area & delay estimates for a LUT.
69	constexpr int64_t kMaxDividendForCompressedLUT = 64 * 64 - 1;
70	
71	// For the given comparison Op, returns the op op_inverse for which the
72	// following identity holds:
73	//   op(x, y) == !op_inverse(x, y)
74	Op CompareOpInverse(Op op) {
75	  switch (op) {
76	    case Op::kEq:
77	      return Op::kNe;
78	    case Op::kNe:
79	      return Op::kEq;
80	    case Op::kSGe:
81	      return Op::kSLt;
82	    case Op::kUGe:
83	      return Op::kULt;
84	    case Op::kSGt:
85	      return Op::kSLe;
86	    case Op::kUGt:
87	      return Op::kULe;
88	    case Op::kSLe:
89	      return Op::kSGt;
90	    case Op::kULe:
91	      return Op::kUGt;
92	    case Op::kSLt:
93	      return Op::kSGe;
94	    case Op::kULt:
95	      return Op::kUGe;
96	    default:
97	      LOG(FATAL) << "Op is not comparison: " << OpToString(op);
98	  }
99	}
100	
101	// Returns true if `node` is a comparison between bits-typed values.
102	bool IsBitsCompare(Node* node) {
103	  return OpIsCompare(node->op()) && node->operand(0)->GetType()->IsBits();
104	}
105	
106	// Matches the given node to the following expressions:
107	//
108	//  Select(UGt(x, LIMIT), cases=[x, LIMIT])
109	//  Select(UGt(x, LIMIT), cases=[x], default=LIMIT)
110	//  PrioritySelect(UGt(x, LIMIT), cases=[LIMIT], default=x)
111	//
112	// Where LIMIT is a literal. Returns a ClampExpr containing 'x' and 'LIMIT'
113	// values.
114	struct ClampExpr {
115	  Node* node;
116	  Bits upper_limit;
117	};
118	std::optional<ClampExpr> MatchClampUpperLimit(Node* n,
119	                                              const QueryEngine& query_engine) {
120	  Node* cmp;
121	  Node* consequent;
122	  Node* alternative;
123	  if (n->Is<Select>()) {
124	    Select* select = n->As<Select>();
125	    size_t total_cases =
126	        select->cases().size() + (select->default_value().has_value() ? 1 : 0);
127	    if (total_cases != 2) {
128	      return std::nullopt;
129	    }
130	    cmp = select->selector();
131	    alternative = select->get_case(0);
132	    if (select->default_value().has_value()) {
133	      consequent = *select->default_value();
134	    } else {
135	      consequent = select->get_case(1);
136	    }
137	  } else if (n->Is<PrioritySelect>()) {
138	    PrioritySelect* select = n->As<PrioritySelect>();
139	    if (select->cases().size() != 1) {
140	      return std::nullopt;
141	    }
142	    cmp = select->selector();
143	    consequent = select->get_case(0);
144	    alternative = select->default_value();
145	  } else {
146	    return std::nullopt;
147	  }
148	  if (cmp->op() == Op::kUGt && query_engine.IsFullyKnown(consequent) &&
149	      cmp->operand(1) == consequent && cmp->operand(0) == alternative) {
150	    return ClampExpr{
151	        .node = cmp->operand(0),
152	        .upper_limit = *query_engine.KnownValueAsBits(consequent),
153	    };
154	  }
155	  return std::nullopt;
156	}
157	
158	// The values required to emulate division by a specific divisor.
159	struct UnsignedDivisionConstants {
160	  // dividend and divisor must be < 2^N
161	  const int64_t N;
162	
163	  // multiplies the dividend
164	  const BigInt m;
165	
166	  // right shift amount before the multiply
167	  const int64_t pre_shift;
168	
169	  // right shift amount after the multiply
170	  const int64_t post_shift;
171	};
172	
173	// Returns (m, post_shift, l). Used in optimizing division by
174	// a constant.
175	//
176	// Args:
177	//   N: the smallest value that satisfies: (divisor < 2^N) and (numerator < 2^N)
178	//   divisor: the divisor, a compile-time constant.
179	//   precision: bits of precision needed. Frequently this is N, and
180	//    sometimes an optimization makes this smaller.
181	//
182	// With respect to the paper: prec = precision, sh_post = post_shift
183	std::tuple<BigInt, int64_t, int64_t> ChooseMultiplier(int64_t N, BigInt divisor,
184	                                                      int64_t precision) {
185	  const int64_t l = BigInt::CeilingLog2(divisor);
186	  int64_t post_shift = l;
187	
188	  // Possible optimization: the expression below can also be computed as:
189	  //      ((2^l - divisor) * 2^N)
190	  // floor(---------------------) + 2^N
191	  //      (        divisor      )
192	  BigInt m_low = BigInt::Exp2(N + l) / divisor;
193	
194	  // Possible optimization: the expression below can also be computed as:
195	  //      (2^(N+l-p) + 2^N * (2^l - divisor))
196	  // floor(---------------------------------) + 2^N
197	  //      (        divisor                  )
198	
199	  const BigInt two_n_l = BigInt::Exp2(N + l);
200	  const BigInt two_n_l_p = BigInt::Exp2(N + l - precision);
201	  BigInt m_high = (two_n_l + two_n_l_p) / divisor;
202	
203	  const BigInt two = BigInt::Exp2(1);
204	
205	  while ((m_low / two) < (m_high / two) && (post_shift > 0)) {
206	    m_low = m_low / two;
207	    m_high = m_high / two;
208	    post_shift = post_shift - 1;
209	  }
210	
211	  return std::make_tuple(m_high, post_shift, l);
212	}
213	
214	UnsignedDivisionConstants ComputeUnsignedDivisionConstants(int64_t num_bits,
215	                                                           BigInt divisor) {
216	  CHECK(!BigInt::IsPowerOfTwo(divisor))
217	      << "divide by power of two isn't handled by UnsignedDivision; other code "
218	         "handles that case.";
219	
220	  auto [m, post_shift, ignored] = ChooseMultiplier(num_bits, divisor, num_bits);
221	
222	  int64_t pre_shift;
223	  if (m >= BigInt::Exp2(num_bits) && BigInt::IsEven(divisor)) {
224	    auto [divisor_odd_factor, exponent] = BigInt::FactorizePowerOfTwo(divisor);
225	    pre_shift = exponent;
226	    std::tie(m, post_shift, ignored) =
227	        ChooseMultiplier(num_bits, divisor_odd_factor, num_bits - exponent);
228	  } else {
229	    pre_shift = 0;
230	  }
231	
232	  return UnsignedDivisionConstants{num_bits, m, pre_shift, post_shift};
233	}
234	
235	// Narrows or extends n.
236	//
237	// Extends when resize_to > n.BitCount. If n_is_signed, sign extension is
238	// performed, otherwise zero extension.
239	//
240	// Narrows (discards most significant bits) when resize_to < n.BitCount.
241	//
242	// Is identity function when resize_to == n.BitCount.
243	//
244	// Assumes resize_to >= 0.
245	absl::StatusOr<Node*> NarrowOrExtend(Node* n, bool n_is_signed,
246	                                     int64_t resize_to) {
247	  CHECK_GE(resize_to, 0);
248	
249	  if (n->BitCountOrDie() < resize_to) {
250	    return n->function_base()->MakeNode<ExtendOp>(
251	        n->loc(), n,
252	        /*new_bit_count=*/resize_to, n_is_signed ? Op::kSignExt : Op::kZeroExt);
253	  }
254	
255	  if (n->BitCountOrDie() > resize_to) {
256	    return n->function_base()->MakeNode<BitSlice>(n->loc(), n,
257	                                                  /*start=*/0,
258	                                                  /*width=*/resize_to);
259	  }
260	
261	  return n;
262	}
