264	struct BinaryOpWithConstant {
265	  Node* operand;
266	  Value constant;
267	  bool constant_on_lhs;
268	  Op op;
269	};
270	
271	// Matches the given node as binary operation performed with a constant on the
272	// lhs or rhs. If match succeeds, returns BinaryOpWithConstant metadata.
273	std::optional<BinaryOpWithConstant> MatchBinaryOpWithConstant(
274	    Node* node, const QueryEngine& query_engine) {
275	  if (node->operand_count() != 2) {
276	    return std::nullopt;
277	  }
278	  if (std::optional<Value> constant = query_engine.KnownValue(node->operand(0));
279	      constant.has_value()) {
280	    return BinaryOpWithConstant{.operand = node->operand(1),
281	                                .constant = *constant,
282	                                .constant_on_lhs = true,
283	                                .op = node->op()};
284	  }
285	  if (std::optional<Value> constant = query_engine.KnownValue(node->operand(1));
286	      constant.has_value()) {
287	    return BinaryOpWithConstant{.operand = node->operand(0),
288	                                .constant = *constant,
289	                                .constant_on_lhs = false,
290	                                .op = node->op()};
291	  }
292	  return std::nullopt;
293	}
