295	// Match a pattern where the result of an injective operation is compared for
296	// equality/inequality against a constant. An example might be:
297	//
298	//   X + C_0 == C_1
299	//
300	// Where C_0 and C_1 are constants. In this case the operation `X + C_0` is
301	// injective, that is, the result of `X + C_0` strictly determines the value of
302	// `X`. In this case you can simplify the above to:
303	//
304	//   X == C_1 - C_0
305	//
306	// Operations handled are `kAdd` and `kSub`.
307	absl::StatusOr<bool> MatchComparisonOfInjectiveOp(
308	    Node* node, const QueryEngine& query_engine) {
309	  if (!node->GetType()->IsBits()) {
310	    return false;
311	  }
312	  std::optional<BinaryOpWithConstant> compare =
313	      MatchBinaryOpWithConstant(node, query_engine);
314	  if (!compare.has_value()) {
315	    return false;
316	  }
317	  // TODO(allight): Support other comparisons when possible.
318	  // NB This is required for the subtraction simplifications to be accurate
319	  // because otherwise the direction of the comparison might need to change.
320	  if (compare->op != Op::kEq && compare->op != Op::kNe) {
321	    return false;
322	  }
323	  std::optional<BinaryOpWithConstant> binary_op =
324	      MatchBinaryOpWithConstant(compare->operand, query_engine);
325	  if (!binary_op.has_value()) {
326	    return false;
327	  }
328	  if (binary_op->op != Op::kAdd && binary_op->op != Op::kSub &&
329	      binary_op->op != Op::kUMul) {
330	    return false;
331	  }
332	  if (binary_op->op == Op::kUMul) {
333	    // Check if the binary op can overflow.
334	    int64_t op_width = compare->operand->BitCountOrDie();
335	    std::optional<SharedLeafTypeTree<TernaryVector>> op_ternary =
336	        query_engine.GetTernary(binary_op->operand);
337	    int64_t op_size =
338	        op_ternary.has_value()
339	            ? ternary_ops::MinimumUnsignedBitCount(op_ternary->Get({}))
340	            : binary_op->operand->BitCountOrDie();
341	    int64_t const_size = binary_op->constant.bits().bit_count() -
342	                         binary_op->constant.bits().CountLeadingZeros();
343	    // If op_width is greater than or equal to the combined sizes of the
344	    // operands then overflow is impossible since there would need to be at
345	    // least one more add to hit the next bit.
346	    if (op_width < op_size + const_size) {
347	      // Overflow possible.
348	      return false;
349	    }
350	  }
351	  Bits solution;
352	  Node* new_op;
353	  if (binary_op->op == Op::kAdd) {
354	    // (X + C_0) cmp C_1  => x cmp C_1 - C_0
355	    new_op = binary_op->operand;
356	    solution =
357	        bits_ops::Sub(compare->constant.bits(), binary_op->constant.bits());
358	  } else if (binary_op->op == Op::kSub) {
359	    new_op = binary_op->operand;
360	    if (binary_op->constant_on_lhs) {
361	      // (C_0 - X) cmp C_1  => x cmp C_0 - C_1
362	      solution =
363	          bits_ops::Sub(binary_op->constant.bits(), compare->constant.bits());
364	    } else {
365	      // (X - C_0) cmp C_1  => x cmp C_0 + C_1
366	      solution =
367	          bits_ops::Add(compare->constant.bits(), binary_op->constant.bits());
368	    }
369	  } else {
370	    XLS_RET_CHECK_EQ(binary_op->op, Op::kUMul);
371	    // Need to be careful not to break the case where the comparison is actually
372	    // impossible to satisfy or reject (eg 2*x == 3).
373	    bool const_is_zero = compare->constant.bits().IsZero();
374	    bool mul_is_zero = binary_op->constant.bits().IsZero();
375	    bool result_is_possible =
376	        bits_ops::UMod(compare->constant.bits(), binary_op->constant.bits())
377	            .IsZero();
378	    if (const_is_zero && mul_is_zero) {
379	      VLOG(2) << "FOUND: Constant umul comparison.";
380	      XLS_RETURN_IF_ERROR(
381	          node->ReplaceUsesWithNew<Literal>(Value::Bool(compare->op == Op::kEq))
382	              .status());
383	      return true;
384	    }
385	    if (const_is_zero) {
386	      solution = Bits(binary_op->operand->BitCountOrDie());
387	    } else if (mul_is_zero || !result_is_possible) {
388	      VLOG(2) << "FOUND: Constant umul comparison.";
389	      XLS_RETURN_IF_ERROR(
390	          node->ReplaceUsesWithNew<Literal>(Value::Bool(compare->op == Op::kNe))
391	              .status());
392	      return true;
393	    } else {
394	      int64_t desired_bits = std::max({binary_op->constant.bits().bit_count(),
395	                                       compare->constant.bits().bit_count(),
396	                                       binary_op->operand->BitCountOrDie()});
397	      auto extend_to_bits = [&](const Bits& b) -> Bits {
398	        if (b.bit_count() >= desired_bits) {
399	          return b;
400	        }
401	        return bits_ops::ZeroExtend(b, desired_bits);
402	      };
403	      // (C_0 * X) cmp C_1 => X cmp C_1 / C_0
404	      solution = bits_ops::UDiv(extend_to_bits(compare->constant.bits()),
405	                                extend_to_bits(binary_op->constant.bits()));
406	    }
407	    if (binary_op->operand->BitCountOrDie() == solution.bit_count()) {
408	      new_op = binary_op->operand;
409	    } else {
410	      XLS_ASSIGN_OR_RETURN(
411	          new_op, node->function_base()->MakeNodeWithName<ExtendOp>(
412	                      binary_op->operand->loc(), binary_op->operand,
413	                      solution.bit_count(), Op::kZeroExt,
414	                      NodeNameFormat("%s_extended", binary_op->operand)));
415	    }
416	  }
417	  XLS_ASSIGN_OR_RETURN(
418	      Literal * new_literal,
419	      node->function_base()->MakeNode<Literal>(node->loc(), Value(solution)));
420	
421	  VLOG(2) << "FOUND: compairson of injective operation.";
422	  XLS_RETURN_IF_ERROR(
423	      node->ReplaceUsesWithNew<CompareOp>(new_op, new_literal, compare->op)
424	          .status());
425	  return true;
426	}
