428	struct CompressedLUTEntry {
429	  Value value;
430	  int64_t cutoff;
431	};
432	struct CompressedLUT {
433	  std::vector<Value> uncompressed_values;
434	  int64_t uncompressed_cutoff;
435	  std::vector<CompressedLUTEntry> compressed_entries;
436	  Value past_the_end;
437	};
438	
439	CompressedLUT CompressLUT(std::vector<Value> entries, Value past_the_end) {
440	  // Split the lookup table into two parts:
441	  // - the uncompressed section; lookup here is done with a simple array_index,
442	  //   and we only compress the very last value (using array_index clamping).
443	  // - the compressed section; lookup here is done with a priority select.
444	  // The LUT logic should decide whether to use the uncompressed or compressed
445	  // section by comparing the index to the `uncompressed_cutoff`.
446	  CompressedLUT result;
447	  result.uncompressed_cutoff = 0;
448	  result.uncompressed_values.reserve(entries.size());
449	  result.compressed_entries.reserve(entries.size());
450	  result.past_the_end = past_the_end;
451	
452	  for (int64_t i = 0; i < entries.size() && i < kMaxConstantDividendLUTSize;
453	       ++i) {
454	    result.uncompressed_values.push_back(std::move(entries[i]));
455	    result.uncompressed_cutoff = i;
456	  }
457	  while (
458	      result.uncompressed_values.size() >= 2 &&
459	      result.uncompressed_values.back() ==
460	          result.uncompressed_values[result.uncompressed_values.size() - 2]) {
461	    // The last uncompressed value is repeated; remove it, relying on
462	    // `array_index`'s clamping behavior to compress this case into the previous
463	    // value.
464	    result.uncompressed_values.pop_back();
465	  }
466	  while (result.uncompressed_cutoff + 1 < entries.size() &&
467	         entries[result.uncompressed_cutoff + 1] ==
468	             result.uncompressed_values.back()) {
469	    // Absorb the next entry into the uncompressed section, relying on
470	    // `array_index`'s clamping behavior to compress this case.
471	    result.uncompressed_cutoff += 1;
472	  }
473	
474	  for (int64_t i = result.uncompressed_cutoff + 1; i < entries.size(); ++i) {
475	    if (!result.compressed_entries.empty() &&
476	        result.compressed_entries.back().value == entries[i]) {
477	      result.compressed_entries.back().cutoff++;
478	      continue;
479	    }
480	    result.compressed_entries.push_back(CompressedLUTEntry{
481	        .value = std::move(entries[i]),
482	        .cutoff = i,
483	    });
484	  }
485	  while (!result.compressed_entries.empty() &&
486	         result.compressed_entries.back().value == past_the_end) {
487	    // The last compressed entry is equal to the `past_the_end_value`, so it's
488	    // redundant.
489	    result.compressed_entries.pop_back();
490	  }
491	  return result;
492	}
493	
494	absl::StatusOr<Node*> GenerateLUT(CompressedLUT lut, Node* index,
495	                                  SourceInfo loc = SourceInfo()) {
496	  FunctionBase* fb = index->function_base();
497	
498	  XLS_ASSIGN_OR_RETURN(Node * past_the_end,
499	                       fb->MakeNode<Literal>(loc, lut.past_the_end));
500	  if (lut.uncompressed_values.empty() && lut.compressed_entries.empty()) {
501	    // The lookup table is empty.
502	    return past_the_end;
503	  }
504	
505	  std::vector<Node*> predicates;
506	  std::vector<Node*> cases;
507	  predicates.reserve(lut.compressed_entries.size() + 1);
508	  cases.reserve(lut.compressed_entries.size() + 1);
509	
510	  if (!lut.uncompressed_values.empty()) {
511	    if (lut.compressed_entries.empty() &&
512	        lut.uncompressed_cutoff == lut.uncompressed_values.size() - 1 &&
513	        lut.past_the_end != lut.uncompressed_values.back()) {
514	      // We can fit the past-the-end value into the uncompressed section,
515	      // relying on `array_index`'s clamping behavior to handle the past-the-end
516	      // case without a comparison & priority select.
517	      lut.uncompressed_values.push_back(lut.past_the_end);
518	    }
519	
520	    XLS_ASSIGN_OR_RETURN(
521	        Node * uncompressed_table,
522	        fb->MakeNode<Literal>(loc, Value::ArrayOrDie(lut.uncompressed_values)));
523	    XLS_ASSIGN_OR_RETURN(
524	        Node * uncompressed_lookup,
525	        fb->MakeNode<ArrayIndex>(loc, uncompressed_table,
526	                                 absl::MakeConstSpan({index})));
527	
528	    if (lut.compressed_entries.empty() &&
529	        lut.past_the_end == lut.uncompressed_values.back()) {
530	      // No need for a priority select; the uncompressed lookup already covers
531	      // all cases.
532	      return uncompressed_lookup;
533	    }
534	
535	    cases.push_back(uncompressed_lookup);
536	
537	    XLS_ASSIGN_OR_RETURN(
538	        Node * in_uncompressed,
539	        CompareLiteral(index, lut.uncompressed_cutoff, Op::kULe));
540	    predicates.push_back(in_uncompressed);
541	  }
542	
543	  for (const auto& [value, cutoff] : lut.compressed_entries) {
544	    XLS_ASSIGN_OR_RETURN(Node * predicate,
545	                         CompareLiteral(index, cutoff, Op::kULe));
546	    XLS_ASSIGN_OR_RETURN(Node * case_node, fb->MakeNode<Literal>(loc, value));
547	    predicates.push_back(predicate);
548	    cases.push_back(case_node);
549	  }
550	
551	  CHECK(!predicates.empty());
552	  // Reverse the order of the predicates to match MSB-first concat semantics.
553	  std::reverse(predicates.begin(), predicates.end());
554	  XLS_ASSIGN_OR_RETURN(Node * selector,
555	                       ConcatIfNeeded(fb, predicates, /*name=*/"", loc));
556	  return fb->MakeNode<PrioritySelect>(loc, selector, cases,
557	                                      /*default_value=*/past_the_end);
558	}
