560	// Matches unsigned integer division with one operand constant.
561	//
562	// If the divisor is constant, replaces with a multiply and shift(s).
563	//
564	// If the dividend is constant and reasonably small, replaces with a lookup
565	// table.
566	//
567	// Returns 'true' if the IR was modified (uses of node was replaced with a
568	// different expression).
569	//
570	// In accordance with XLS semantics
571	// (https://google.github.io/xls/ir_semantics/), quotient is rounded towards 0.
572	//
573	// Note: the source for the algorithms used to optimize division by constant is
574	// "Division by Invariant Integers using Multiplication"
575	// https://gmplib.org/~tege/divcnst-pldi94.pdf
576	absl::StatusOr<bool> MatchUnsignedDivideByConstant(
577	    Node* original_div_op, const QueryEngine& query_engine) {
578	  if (original_div_op->op() != Op::kUDiv) {
579	    return false;
580	  }
581	  FunctionBase* fb = original_div_op->function_base();
582	  Node* dividend = original_div_op->operand(0);
583	  Node* divisor = original_div_op->operand(1);
584	  int64_t bit_count = original_div_op->BitCountOrDie();
585	
586	  if (query_engine.IsFullyKnown(divisor)) {
587	    Bits rhs = *query_engine.KnownValueAsBits(divisor);
588	    if (!rhs.IsPowerOfTwo()  // power of two is handled elsewhere.
589	        && !rhs.IsZero()     // div by 0 is handled elsewhere
590	    ) {
591	      const SourceInfo loc = original_div_op->loc();
592	
593	      UnsignedDivisionConstants division_constants =
594	          ComputeUnsignedDivisionConstants(dividend->BitCountOrDie(),
595	                                           BigInt::MakeUnsigned(rhs));
596	
597	      // In the paper, there is a case for m >= 2^N.
598	      // Comparing the "large m" case to the m < 2^N case (AKA "small m case"),
599	      // the "large m" case has:
600	      //  * 2 more subs
601	      //  * 1 more add
602	      //  * a narrower multiply (one operand is 1 bit narrower - details below)
603	      //
604	      // I believe the large m case only exists because the paper assumes that
605	      // the computer's widest multiplier is N bits. Obviously we can synthesize
606	      // a wider multiplier. I'm not sure what's more optimal (in terms of
607	      // latency, area, power):
608	      // * have a separate large m case
609	      // * fold the large m case into the small m case
610	      //
611	      // Careful reading reveals that in the large m case, m is just 1 bit wider
612	      // than in the small m case. That means that the penalty for reusing the
613	      // small m algorithm for the large m case is small: one multiplier operand
614	      // is 1 bit wider. I also verified this empirically for all divisors in
615	      // [1, 2^24].
616	      //
617	      // It's less work to reuse the small m case, so that's what we do.
618	      //
619	      // If you want to add the large m case, the condition is:
620	      // if (division_constants.m >= Exp2<uint64_t>(division_constants.N))
621	      // the expression to implement is:
622	      // t1 = mulhi(m-Exp2<uint64_t>(N), numerator)
623	      // return SRL(t1 + SRL(numerator-t1,1), post_shift-1)
624	
625	      // The operations below implement the small m case. The expression is:
626	      // SRL(mulhi(m, SRL(numerator, pre_shift)), post_shift)
627	
628	      // The dividend after pre_shift.
629	      Node* shift_dividend;
630	      if (division_constants.pre_shift > 0) {
631	        // SRL(dividend, pre_shift)
632	        //
633	        // We use BitSlice instead of SRL, because BitSlice produces a
634	        // narrower result (and the extra bits returned by SRL are zeros).
635	        XLS_ASSIGN_OR_RETURN(
636	            shift_dividend,
637	            fb->MakeNode<BitSlice>(
638	                loc, dividend,
639	                /*start=*/division_constants.pre_shift,
640	                /*width=*/
641	                dividend->BitCountOrDie() - division_constants.pre_shift));
642	      } else {
643	        shift_dividend = dividend;
644	      }
645	
646	      // Mul(m, ...)
647	      XLS_ASSIGN_OR_RETURN(
648	          Node * multiplicand_literal,
649	          fb->MakeNode<Literal>(loc,
650	                                Value(division_constants.m.ToUnsignedBits())));
651	      XLS_ASSIGN_OR_RETURN(
652	          Node * multiply,
653	          fb->MakeNode<ArithOp>(loc, multiplicand_literal, shift_dividend,
654	                                multiplicand_literal->BitCountOrDie() +
655	                                    shift_dividend->BitCountOrDie(),
656	                                Op::kUMul));
657	
658	      // Notes on how this works:
659	      // m / 2^post_shift ~= 1/divisor
660	      // m is effectively a fixed point value with N fractional bits (and
661	      // frequently 0 but sometimes more than 0 integer bits).
662	      // We're only interested in the integer part of dividend/divisor, thus
663	      // we're only interested in the integer part of (dividend * m). So we
664	      // discard the fractional bits of (m * dividend), via BitSlice.
665	      XLS_ASSIGN_OR_RETURN(
666	          Node * integer_part_of_product,
667	          fb->MakeNode<BitSlice>(
668	              loc, multiply,
669	              /*start=*/division_constants.N,
670	              /*width=*/
671	              multiply->BitCountOrDie() - division_constants.N));
672	
673	      // SRL(..., post_shift)
674	      Node* post_shift_node = integer_part_of_product;
675	      if (division_constants.post_shift > 0) {
676	        XLS_ASSIGN_OR_RETURN(
677	            Node * shift_amount_literal,
678	            fb->MakeNode<Literal>(
679	                loc, Value(UBits(division_constants.post_shift,
680	                                 Bits::MinBitCountUnsigned(
681	                                     division_constants.post_shift)))));
682	        XLS_ASSIGN_OR_RETURN(
683	            post_shift_node,
684	            fb->MakeNode<BinOp>(loc, integer_part_of_product,
685	                                shift_amount_literal, Op::kShrl));
686	      }
687	
688	      XLS_ASSIGN_OR_RETURN(Node * resize_post_shift,
689	                           NarrowOrExtend(post_shift_node, false, bit_count));
690	
691	      XLS_RETURN_IF_ERROR(original_div_op->ReplaceUsesWith(resize_post_shift));
692	      return true;
693	    }
694	  }
695	
696	  if (!query_engine.IsFullyKnown(dividend)) {
697	    return false;
698	  }
699	  Bits dividend_bits = *query_engine.KnownValueAsBits(dividend);
700	  int64_t constant_dividend =
701	      bits_ops::UnsignedBitsToSaturatedInt64(dividend_bits);
702	  if (constant_dividend > kMaxDividendForCompressedLUT) {
703	    return false;
704	  }
705	
706	  VLOG(2) << absl::StreamFormat(
707	      "FOUND: UDiv of small constant dividend u%d:%d; replacing with lookup "
708	      "table",
709	      dividend_bits.bit_count(), constant_dividend);
710	
711	  // Implement the division with a simple lookup table, rounding quotient
712	  // towards 0.
713	  std::vector<Value> lut_entries;
714	  lut_entries.reserve(constant_dividend + 1);
715	  lut_entries.push_back(Value(Bits::AllOnes(bit_count)));
716	  for (int64_t i = 1; i <= constant_dividend; ++i) {
717	    lut_entries.push_back(Value(UBits(constant_dividend / i, bit_count)));
718	  }
719	
720	  // Compress the lookup table to avoid excessively-large arrays.
721	  CompressedLUT lut =
722	      CompressLUT(std::move(lut_entries),
723	                  /*past_the_end=*/ZeroOfType(original_div_op->GetType()));
724	  XLS_ASSIGN_OR_RETURN(
725	      Node * lookup_result,
726	      GenerateLUT(std::move(lut), divisor, original_div_op->loc()));
727	  XLS_RETURN_IF_ERROR(original_div_op->ReplaceUsesWith(lookup_result));
728	  return true;
729	}
730	
731	// Matches signed integer division with one operand constant.
732	//
733	// If the divisor is constant, replaces with a multiply and shift(s).
734	//
735	// If the dividend is constant and reasonably small, replaces with a lookup
736	// table.
737	//
738	// Returns 'true' if the IR was modified (uses of node was replaced with a
739	// different expression).
740	//
741	// In accordance with XLS semantics
742	// (https://google.github.io/xls/ir_semantics/), quotient is rounded towards 0.
743	//
744	// Note: the source for the algorithms used to optimize divison by constant is
745	// "Division by Invariant Integers using Multiplication"
746	// https://gmplib.org/~tege/divcnst-pldi94.pdf
747	absl::StatusOr<bool> MatchSignedDivideByConstant(
748	    Node* original_div_op, const QueryEngine& query_engine) {
749	  if (original_div_op->op() != Op::kSDiv) {
750	    return false;
751	  }
752	  FunctionBase* fb = original_div_op->function_base();
753	  Node* dividend = original_div_op->operand(0);
754	  Node* divisor = original_div_op->operand(1);
755	  int64_t bit_count = original_div_op->BitCountOrDie();
756	
757	  // TODO paper mentions overflow when n=-(2^(N-1)) and d=-1. Make sure I handle
758	  // that correctly. I'm not sure if Figure 5.2 does.
759	  if (query_engine.IsFullyKnown(divisor)) {
760	    Bits rhs = *query_engine.KnownValueAsBits(divisor);
761	    if (!rhs.IsZero()  // div by 0 is handled elsewhere
762	    ) {
763	      const SourceInfo loc = original_div_op->loc();
764	
765	      const BigInt divisor = BigInt::MakeSigned(rhs);
766	      const BigInt magnitude_divisor = BigInt::Absolute(divisor);
767	      const bool divisor_negative = divisor < BigInt::Zero();
768	
769	      const int64_t n = dividend->BitCountOrDie();
770	      auto [m, post_shift, clog2_divisor] =
771	          ChooseMultiplier(n, magnitude_divisor, n - 1);
772	
773	      auto maybe_negate = [divisor_negative, &fb,
774	                           &loc](Node* quotient) -> absl::StatusOr<Node*> {
775	        if (divisor_negative) {
776	          return fb->MakeNode<UnOp>(loc, quotient, Op::kNeg);
777	        }
778	
779	        return quotient;
780	      };
781	
782	      if (magnitude_divisor == BigInt::One()) {
783	        XLS_ASSIGN_OR_RETURN(Node * negate, maybe_negate(dividend));
784	        XLS_RETURN_IF_ERROR(original_div_op->ReplaceUsesWith(negate));
785	        return true;
786	      }
787	
788	      if (magnitude_divisor == BigInt::Exp2(clog2_divisor)) {
789	        // case: |d| = 2^l
790	        // q = SRA(n + SRL(SRA(n, l − 1), N − l), l)
791	
792	        // SRA(n, l − 1)
793	        const int64_t first_sra_amount = clog2_divisor - 1;
794	        Node* first_sra = dividend;
795	        if (first_sra_amount > 0) {
796	          XLS_ASSIGN_OR_RETURN(
797	              Node * first_sra_literal,
798	              fb->MakeNode<Literal>(
799	                  loc, Value(UBits(first_sra_amount, Bits::MinBitCountUnsigned(
800	                                                         first_sra_amount)))));
801	          XLS_ASSIGN_OR_RETURN(
802	              first_sra,
803	              fb->MakeNode<BinOp>(loc, dividend, first_sra_literal, Op::kShra));
804	        }
805	
806	        // SRL(..., N − l)
807	        const int64_t shift_right_logical_amount = n - clog2_divisor;
808	        Node* srl = first_sra;
809	        if (shift_right_logical_amount > 0) {
810	          XLS_ASSIGN_OR_RETURN(
811	              Node * srl_literal,
812	              fb->MakeNode<Literal>(
813	                  loc, Value(UBits(shift_right_logical_amount,
814	                                   Bits::MinBitCountUnsigned(
815	                                       shift_right_logical_amount)))));
816	          XLS_ASSIGN_OR_RETURN(
817	              srl, fb->MakeNode<BinOp>(loc, first_sra, srl_literal, Op::kShrl));
818	        }
819	
820	        // n + SRL(...)
821	        XLS_ASSIGN_OR_RETURN(Node * add,
822	                             fb->MakeNode<BinOp>(loc, dividend, srl, Op::kAdd));
823	
824	        // SRA(..., l)
825	        const int64_t second_sra_amount = clog2_divisor;
826	        Node* second_sra = add;
827	        if (second_sra_amount > 0) {
828	          XLS_ASSIGN_OR_RETURN(
829	              Node * second_sra_literal,
830	              fb->MakeNode<Literal>(
831	                  loc,
832	                  Value(UBits(second_sra_amount,
833	                              Bits::MinBitCountUnsigned(second_sra_amount)))));
834	          XLS_ASSIGN_OR_RETURN(
835	              second_sra,
836	              fb->MakeNode<BinOp>(loc, add, second_sra_literal, Op::kShra));
837	        }
838	
839	        // if d<0 then negate q
840	        XLS_ASSIGN_OR_RETURN(Node * negate, maybe_negate(second_sra));
841	        XLS_RETURN_IF_ERROR(original_div_op->ReplaceUsesWith(negate));
842	        return true;
843	      }
844	
845	      // In the paper, there is a case for m >= 2^N. However, we reuse the
846	      // same logic as for the "small m" case. See comment in
847	      // MatchUnsignedDivide for details.
848	
849	      // q = SRA(MULSH(m, n), post_shift) - XSIGN(n)
850	
851	      // MULSH(m, n)
852	      XLS_ASSIGN_OR_RETURN(Node * multiplicand_literal,
853	                           fb->MakeNode<Literal>(loc, Value(m.ToSignedBits())));
854	      XLS_ASSIGN_OR_RETURN(
855	          Node * multiply,
856	          fb->MakeNode<ArithOp>(
857	              loc, multiplicand_literal, dividend,
858	              multiplicand_literal->BitCountOrDie() + dividend->BitCountOrDie(),
859	              Op::kSMul));
860	
861	      // m is a fixed point value with N fractional bits. So discard the N
862	      // least significant bits of m * dividend. See comment in
863	      // MatchUnsignedDivide for details.
864	      XLS_ASSIGN_OR_RETURN(
865	          Node * integer_part_of_product,
866	          fb->MakeNode<BitSlice>(loc, multiply,
867	                                 /*start=*/n,
868	                                 /*width=*/
869	                                 multiply->BitCountOrDie() - n));
870	
871	      // SRA(..., post_shift)
872	      Node* shift_right = integer_part_of_product;
873	      if (post_shift > 0) {
874	        XLS_ASSIGN_OR_RETURN(
875	            Node * shift_right_literal,
876	            fb->MakeNode<Literal>(
877	                loc, Value(UBits(post_shift,
878	                                 Bits::MinBitCountUnsigned(post_shift)))));
879	        XLS_ASSIGN_OR_RETURN(
880	            shift_right, fb->MakeNode<BinOp>(loc, integer_part_of_product,
881	                                             shift_right_literal, Op::kShra));
882	      }
883	
884	      // XSIGN(n) = SRA(n, N − 1)
885	      const int64_t xsign_sra_amount = n - 1;
886	      XLS_ASSIGN_OR_RETURN(
887	          Node * xsign_sra_literal,
888	          fb->MakeNode<Literal>(
889	              loc, Value(UBits(xsign_sra_amount,
890	                               Bits::MinBitCountUnsigned(xsign_sra_amount)))));
891	      XLS_ASSIGN_OR_RETURN(
892	          Node * xsign,
893	          fb->MakeNode<BinOp>(loc, dividend, xsign_sra_literal, Op::kShra));
894	
895	      // SRA(..., post_shift) - XSIGN(n)
896	      XLS_ASSIGN_OR_RETURN(
897	          Node * resize_shift_right,
898	          NarrowOrExtend(shift_right, true, dividend->BitCountOrDie()));
899	      XLS_ASSIGN_OR_RETURN(
900	          Node * subtract,
901	          fb->MakeNode<BinOp>(loc, resize_shift_right, xsign, Op::kSub));
902	
903	      // if d<0 then negate q
904	      XLS_ASSIGN_OR_RETURN(Node * negate, maybe_negate(subtract));
905	      XLS_RETURN_IF_ERROR(original_div_op->ReplaceUsesWith(negate));
906	      return true;
907	    }
908	  }
909	
910	  if (!query_engine.IsFullyKnown(dividend)) {
911	    return false;
912	  }
913	  Bits dividend_bits = *query_engine.KnownValueAsBits(dividend);
914	  int64_t constant_dividend = dividend_bits.FitsInInt64()
915	                                  ? *dividend_bits.ToInt64()
916	                                  : std::numeric_limits<int64_t>::max();
917	  if (std::abs(constant_dividend) > kMaxDividendForCompressedLUT) {
918	    return false;
919	  }
920	
921	  VLOG(2) << absl::StreamFormat(
922	      "FOUND: SDiv of small constant dividend s%d:%d; replacing with lookup "
923	      "table",
924	      dividend_bits.bit_count(), constant_dividend);
925	
926	  XLS_ASSIGN_OR_RETURN(Node * divisor_is_negative,
927	                       CompareLiteral(divisor, 0, Op::kSLt));
928	  XLS_ASSIGN_OR_RETURN(Node * divisor_is_zero,
929	                       CompareLiteral(divisor, 0, Op::kEq));
930	  XLS_ASSIGN_OR_RETURN(
931	      Node * neg_divisor,
932	      fb->MakeNode<UnOp>(original_div_op->loc(), divisor, Op::kNeg));
933	  XLS_ASSIGN_OR_RETURN(
934	      Node * abs_divisor,
935	      fb->MakeNode<PrioritySelect>(original_div_op->loc(), divisor_is_negative,
936	                                   /*cases=*/absl::MakeConstSpan({neg_divisor}),
937	                                   /*default_value=*/divisor));
938	
939	  // Implement division by the absolute value of the divisor with a simple
940	  // lookup table, rounding quotient towards 0. Give it a zero entry at the
941	  // start to keep the indices aligned, even though we can't use the lookup
942	  // table for the zero-divisor case (since MinSigned != -MaxSigned).
943	  std::vector<Value> entries;
944	  entries.reserve(std::abs(constant_dividend) + 1);
945	  // Add an extra padding entry at the start of the table, to keep the indices
946	  // aligned.
947	  entries.push_back(ZeroOfType(original_div_op->GetType()));
948	  for (int64_t i = 1; i <= std::abs(constant_dividend); ++i) {
949	    entries.push_back(Value(SBits(constant_dividend / i, bit_count)));
950	  }
951	
952	  // Compress the lookup table to avoid excessively-large arrays.
953	  CompressedLUT lut =
954	      CompressLUT(std::move(entries), ZeroOfType(original_div_op->GetType()));
955	  XLS_ASSIGN_OR_RETURN(
956	      Node * result_if_divide_by_pos,
957	      GenerateLUT(std::move(lut), abs_divisor, original_div_op->loc()));
958	
959	  XLS_ASSIGN_OR_RETURN(Node * result_if_divide_by_neg,
960	                       fb->MakeNode<UnOp>(original_div_op->loc(),
961	                                          result_if_divide_by_pos, Op::kNeg));
962	  XLS_ASSIGN_OR_RETURN(
963	      Node * result_if_divide_by_zero,
964	      fb->MakeNode<Literal>(
965	          original_div_op->loc(),
966	          Value(constant_dividend < 0 ? Bits::MinSigned(bit_count)
967	                                      : Bits::MaxSigned(bit_count))));
968	
969	  XLS_ASSIGN_OR_RETURN(
970	      Node * final_selector,
971	      fb->MakeNode<Concat>(
972	          original_div_op->loc(),
973	          absl::MakeConstSpan({divisor_is_negative, divisor_is_zero})));
974	  XLS_RETURN_IF_ERROR(original_div_op
975	                          ->ReplaceUsesWithNew<PrioritySelect>(
976	                              final_selector,
977	                              /*cases=*/
978	                              absl::MakeConstSpan({result_if_divide_by_zero,
979	                                                   result_if_divide_by_neg}),
980	                              /*default_value=*/result_if_divide_by_pos)
981	                          .status());
982	
983	  return true;
984	}
