986	absl::StatusOr<bool> MatchDivByVariablePowerOfTwo(
987	    Node* n, const QueryEngine& query_engine) {
988	  if (!n->OpIn({Op::kUDiv, Op::kSDiv})) {
989	    return false;
990	  }
991	  Node* dividend = n->operand(0);
992	  Node* divisor = n->operand(1);
993	  if (query_engine.IsFullyKnown(divisor)) {
994	    return false;
995	  }
996	  Node* k = nullptr;
997	  // `literal_shift` is also known as L in mathematical notation, but that's
998	  // unreadable in snake case.
999	  int64_t literal_shift = 0;
1000	  if (divisor->op() == Op::kDecode) {
1001	    VLOG(2) << "FOUND: Div by variable power of two (decode(K))";
1002	    k = divisor->operand(0);
1003	  } else if (divisor->op() == Op::kShll) {
1004	    std::optional<Bits> shifted_value =
1005	        query_engine.KnownValueAsBits(divisor->operand(0));
1006	    if (!shifted_value.has_value() || !shifted_value->IsPowerOfTwo()) {
1007	      return false;
1008	    }
1009	    literal_shift = shifted_value->CountTrailingZeros();
1010	    VLOG(2) << absl::StreamFormat(
1011	        "FOUND: Div by variable power of two (2^%d << K)", literal_shift);
1012	    k = divisor->operand(1);
1013	  } else {
1014	    return false;
1015	  }
1016	  XLS_RET_CHECK(k != nullptr);
1017	
1018	  XLS_RET_CHECK_EQ(divisor->BitCountOrDie(), n->BitCountOrDie());
1019	
1020	  int64_t bit_width = n->BitCountOrDie();
1021	  FunctionBase* f = n->function_base();
1022	
1023	  Node* literal_shift_lit = nullptr;
1024	  if (literal_shift > 0) {
1025	    XLS_ASSIGN_OR_RETURN(
1026	        literal_shift_lit,
1027	        f->MakeNode<Literal>(n->loc(), Value(UBits(literal_shift, bit_width))));
1028	  }
1029	
1030	  if (n->op() == Op::kUDiv) {
1031	    // For unsigned division, we can almost just shift right by K+L, except that
1032	    // if K+L is at least the bit width, then we have to return all ones.
1033	    int64_t limit = bit_width - literal_shift;
1034	
1035	    // Since L is constant, shifting right by K+L is most efficient if we do it
1036	    // as (X >> L) >> K.
1037	    Node* shrl_result = dividend;
1038	    if (literal_shift > 0) {
1039	      CHECK(literal_shift_lit != nullptr);
1040	      XLS_ASSIGN_OR_RETURN(shrl_result,
1041	                           f->MakeNode<BinOp>(n->loc(), shrl_result,
1042	                                              literal_shift_lit, Op::kShrl));
1043	    }
1044	    XLS_ASSIGN_OR_RETURN(
1045	        shrl_result, f->MakeNode<BinOp>(n->loc(), shrl_result, k, Op::kShrl));
1046	
1047	    if (Bits::MinBitCountUnsigned(limit) > k->BitCountOrDie()) {
1048	      // K must be smaller than `limit`, since `limit` doesn't even fit in K's
1049	      // bit width. so it's impossible for K+L to be >= bit_width.
1050	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(shrl_result));
1051	      return true;
1052	    }
1053	
1054	    XLS_ASSIGN_OR_RETURN(
1055	        Node * limit_lit,
1056	        f->MakeNode<Literal>(n->loc(),
1057	                             Value(UBits(limit, k->BitCountOrDie()))));
1058	    XLS_ASSIGN_OR_RETURN(Node * is_zero, f->MakeNode<CompareOp>(
1059	                                             n->loc(), k, limit_lit, Op::kUGe));
1060	
1061	    XLS_ASSIGN_OR_RETURN(
1062	        Node * all_ones_lit,
1063	        f->MakeNode<Literal>(n->loc(), Value(Bits::AllOnes(bit_width))));
1064	
1065	    XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<Select>(
1066	                             is_zero,
1067	                             std::vector<Node*>{shrl_result, all_ones_lit},
1068	                             std::nullopt)
1069	                            .status());
1070	    return true;
1071	  }
1072	
1073	  // We're dealing with a signed division; the logic is slightly more complex.
1074	  // Cases:
1075	  // - Div by zero (K + L > N - 1): return max_signed or min_signed, depending
1076	  //                                on the sign of the dividend.
1077	  // - Div by min_signed (K + L = N - 1): return 0, unless dividend is
1078	  //                                      min_signed, then 1.
1079	  // - Otherwise (K + L < N - 1): we can compute the result as
1080	  //                                  (dividend + bias) >> (K + L),
1081	  //                              where the bias should be (1 << (K + L)) - 1 if
1082	  //                              the dividend is negative, or 0 otherwise,
1083	  //                              making sure we round towards zero rather than
1084	  //                              -inf.
1085	  int64_t limit = bit_width - 1 - literal_shift;
1086	
1087	  // Always generate the shift result (default case).
1088	  XLS_ASSIGN_OR_RETURN(
1089	      Node * all_ones_lit,
1090	      f->MakeNode<Literal>(n->loc(), Value(Bits::AllOnes(bit_width))));
1091	  Node* shifted_ones = all_ones_lit;
1092	  if (literal_shift > 0) {
1093	    CHECK(literal_shift_lit != nullptr);
1094	    XLS_ASSIGN_OR_RETURN(shifted_ones,
1095	                         f->MakeNode<BinOp>(n->loc(), shifted_ones,
1096	                                            literal_shift_lit, Op::kShll));
1097	  }
1098	  XLS_ASSIGN_OR_RETURN(
1099	      shifted_ones, f->MakeNode<BinOp>(n->loc(), shifted_ones, k, Op::kShll));
1100	  XLS_ASSIGN_OR_RETURN(Node * bias_for_negative_dividend,
1101	                       f->MakeNode<UnOp>(n->loc(), shifted_ones, Op::kNot));
1102	  XLS_ASSIGN_OR_RETURN(
1103	      Node * negative_dividend,
1104	      f->MakeNode<BitSlice>(n->loc(), dividend, bit_width - 1, 1));
1105	  XLS_ASSIGN_OR_RETURN(
1106	      Node * biased_dividend,
1107	      f->MakeNode<BinOp>(n->loc(), dividend, bias_for_negative_dividend,
1108	                         Op::kAdd));
1109	  XLS_ASSIGN_OR_RETURN(
1110	      Node * adjusted_dividend,
1111	      f->MakeNode<Select>(n->loc(), negative_dividend,
1112	                          std::vector<Node*>{dividend, biased_dividend},
1113	                          /*default_value=*/std::nullopt));
1114	
1115	  // Since L is constant, shifting right by K+L is most efficient if we do it as
1116	  // (X >> L) >> K.
1117	  Node* div_by_shift_result = adjusted_dividend;
1118	  if (literal_shift > 0) {
1119	    CHECK(literal_shift_lit != nullptr);
1120	    XLS_ASSIGN_OR_RETURN(div_by_shift_result,
1121	                         f->MakeNode<BinOp>(n->loc(), div_by_shift_result,
1122	                                            literal_shift_lit, Op::kShra));
1123	  }
1124	  XLS_ASSIGN_OR_RETURN(
1125	      div_by_shift_result,
1126	      f->MakeNode<BinOp>(n->loc(), div_by_shift_result, k, Op::kShra));
1127	
1128	  if (Bits::MinBitCountUnsigned(limit) > k->BitCountOrDie()) {
1129	    // `limit` doesn't fit in K's bit width, so K must be smaller than `limit`.
1130	    // Thus, K + L < N - 1, and we can just return the shift result.
1131	    XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(div_by_shift_result));
1132	    return true;
1133	  }
1134	
1135	  XLS_ASSIGN_OR_RETURN(
1136	      Node * limit_lit,
1137	      f->MakeNode<Literal>(n->loc(), Value(UBits(limit, k->BitCountOrDie()))));
1138	
1139	  XLS_ASSIGN_OR_RETURN(
1140	      Node * divisor_is_zero,
1141	      f->MakeNode<CompareOp>(n->loc(), k, limit_lit, Op::kUGt));
1142	  XLS_ASSIGN_OR_RETURN(Node * divisor_is_min_signed,
1143	                       f->MakeNode<CompareOp>(n->loc(), k, limit_lit, Op::kEq));
1144	
1145	  // We select case 0 when K + L > N - 1 (divisor is zero), case 1 when K + L =
1146	  // N - 1, and the default otherwise.
1147	  XLS_ASSIGN_OR_RETURN(
1148	      Node * selector,
1149	      f->MakeNode<Concat>(n->loc(), std::vector<Node*>{divisor_is_min_signed,
1150	                                                       divisor_is_zero}));
1151	
1152	  // Case 0: Divide by zero
1153	  XLS_ASSIGN_OR_RETURN(
1154	      Node * min_neg_lit,
1155	      f->MakeNode<Literal>(n->loc(),
1156	                           Value(Bits::PowerOfTwo(bit_width - 1, bit_width))));
1157	  XLS_ASSIGN_OR_RETURN(Node * max_pos_lit,
1158	                       f->MakeNode<UnOp>(n->loc(), min_neg_lit, Op::kNot));
1159	  XLS_ASSIGN_OR_RETURN(
1160	      Node * msb, f->MakeNode<BitSlice>(n->loc(), dividend, bit_width - 1, 1));
1161	  XLS_ASSIGN_OR_RETURN(
1162	      Node * div_by_zero_result,
1163	      f->MakeNode<Select>(n->loc(), msb,
1164	                          std::vector<Node*>{max_pos_lit, min_neg_lit},
1165	                          std::nullopt));
1166	
1167	  // Case 1: Divide by min_signed (K + L = N - 1)
1168	  XLS_ASSIGN_OR_RETURN(
1169	      Node * x_is_min_neg,
1170	      f->MakeNode<CompareOp>(n->loc(), dividend, min_neg_lit, Op::kEq));
1171	  XLS_ASSIGN_OR_RETURN(
1172	      Node * zero_lit,
1173	      f->MakeNode<Literal>(n->loc(), Value(UBits(0, bit_width))));
1174	  XLS_ASSIGN_OR_RETURN(
1175	      Node * one_lit,
1176	      f->MakeNode<Literal>(n->loc(), Value(UBits(1, bit_width))));
1177	  XLS_ASSIGN_OR_RETURN(
1178	      Node * div_by_min_signed_result,
1179	      f->MakeNode<Select>(n->loc(), x_is_min_neg,
1180	                          std::vector<Node*>{zero_lit, one_lit}, std::nullopt));
1181	
1182	  XLS_RETURN_IF_ERROR(
1183	      n->ReplaceUsesWithNew<PrioritySelect>(
1184	           selector,
1185	           std::vector<Node*>{div_by_zero_result, div_by_min_signed_result},
1186	           /*default_value=*/div_by_shift_result)
1187	          .status());
1188	  return true;
1189	}
1190	
1191	struct LeadingZerosTrailingOnes {
1192	  int64_t leading_zeros;
1193	  int64_t trailing_ones;
1194	};
1195	
1196	// If the given `bits` is a constant mask of the form 0...01...1, returns the
1197	// number of leading zeros and trailing ones. Otherwise, returns std::nullopt.
1198	std::optional<LeadingZerosTrailingOnes> LsbConstantMask(const Bits& bits) {
1199	  int64_t trailing_zeros = -1;
1200	  int64_t leading_zeros = -1;
1201	  int64_t trailing_ones = -1;
1202	  bool is_mask = bits.HasSingleRunOfSetBits(&leading_zeros, &trailing_ones,
1203	                                            &trailing_zeros);
1204	
1205	  if (!is_mask || trailing_zeros != 0) {
1206	    return std::nullopt;
1207	  }
1208	
1209	  return LeadingZerosTrailingOnes{
1210	      .leading_zeros = leading_zeros,
1211	      .trailing_ones = trailing_ones,
1212	  };
1213	}
1214	
1215	// MatchArithPatterns matches simple tree patterns to find opportunities
1216	// for simplification, such as adding a zero, multiplying by 1, etc.
1217	//
1218	// Return 'true' if the IR was modified (uses of node was replaced with a
1219	// different expression).
1220	absl::StatusOr<bool> MatchArithPatterns(int64_t opt_level, Node* n,
1221	                                        const QueryEngine& query_engine) {
1222	  // Pattern: Add(Not(x), 1) => Neg(x)
1223	  //
1224	  // In two's complement arithmetic: ~x + 1 == -x (mod 2^N).
1225	  if (n->op() == Op::kAdd) {
1226	    Node* negated = nullptr;
1227	    if (n->operand(0)->op() == Op::kNot &&
1228	        IsLiteralUnsignedOne(n->operand(1))) {
1229	      negated = n->operand(0)->operand(0);
1230	    } else if (n->operand(1)->op() == Op::kNot &&
1231	               IsLiteralUnsignedOne(n->operand(0))) {
1232	      // Handle the commuted operand ordering as well.
1233	      negated = n->operand(1)->operand(0);
1234	    }
1235	    if (negated != nullptr) {
1236	      VLOG(2) << "FOUND: Add(Not(x), 1)";
1237	      XLS_RETURN_IF_ERROR(
1238	          n->ReplaceUsesWithNew<UnOp>(negated, Op::kNeg).status());
1239	      return true;
1240	    }
1241	  }
1242	
1243	  // Pattern: UDiv/UMul/SMul by a positive power of two.
1244	  if ((n->op() == Op::kSMul || n->op() == Op::kUMul || n->op() == Op::kUDiv) &&
1245	      query_engine.IsFullyKnown(n->operand(1))) {
1246	    const Bits rhs = *query_engine.KnownValueAsBits(n->operand(1));
1247	    const bool is_signed = n->op() == Op::kSMul;
1248	    if (rhs.IsPowerOfTwo() &&
1249	        (!is_signed || (is_signed && bits_ops::SGreaterThan(rhs, 0)))) {
1250	      VLOG(2) << "FOUND: Div/Mul by positive power of two";
1251	      // Extend/trunc operand 0 (the non-literal operand) to the width of the
1252	      // div/mul then shift by a constant amount.
1253	      XLS_ASSIGN_OR_RETURN(
1254	          Node * adjusted_lhs,
1255	          NarrowOrExtend(n->operand(0), is_signed, n->BitCountOrDie()));
1256	      XLS_ASSIGN_OR_RETURN(Node * shift_amount,
1257	                           n->function_base()->MakeNode<Literal>(
1258	                               n->loc(), Value(UBits(rhs.CountTrailingZeros(),
1259	                                                     rhs.bit_count()))));
1260	      Op shift_op;
1261	      if (n->op() == Op::kSMul || n->op() == Op::kUMul) {
1262	        // Multiply operation is replaced with shift left;
1263	        shift_op = Op::kShll;
1264	      } else {
1265	        // Unsigned divide operation is replaced with shift right logical.
1266	        shift_op = Op::kShrl;
1267	      }
1268	      VLOG(2) << "FOUND: div/mul of positive power of two";
1269	      XLS_RETURN_IF_ERROR(
1270	          n->ReplaceUsesWithNew<BinOp>(adjusted_lhs, shift_amount, shift_op)
1271	              .status());
1272	      return true;
1273	    }
1274	  }
1275	
1276	  // Pattern: UMod/SMod by a literal.
1277	  if (n->OpIn({Op::kUMod, Op::kSMod}) &&
1278	      query_engine.IsFullyKnown(n->operand(1))) {
1279	    const Bits rhs = *query_engine.KnownValueAsBits(n->operand(1));
1280	    const bool is_signed = n->op() == Op::kSMod;
1281	
1282	    if (rhs.IsOne() || rhs.IsZero()) {
1283	      VLOG(2) << "FOUND: UMod/SMod by one or zero";
1284	      XLS_RETURN_IF_ERROR(
1285	          n->ReplaceUsesWithNew<Literal>(ZeroOfType(n->GetType())).status());
1286	      return true;
1287	    }
1288	
1289	    if (rhs.IsPowerOfTwo() &&
1290	        (!is_signed || (is_signed && bits_ops::SGreaterThan(rhs, 0)))) {
1291	      VLOG(2) << "FOUND: UMod/SMod by a positive power of two";
1292	      // Truncate operand 0 to the relevant low bits, then zero-extend it to the
1293	      // width of the mod.
1294	      XLS_ASSIGN_OR_RETURN(Node * truncated_lhs,
1295	                           NarrowOrExtend(n->operand(0), /*n_is_signed=*/false,
1296	                                          rhs.CountTrailingZeros()));
1297	      XLS_ASSIGN_OR_RETURN(Node * nonnegative_result,
1298	                           NarrowOrExtend(truncated_lhs, /*n_is_signed=*/false,
1299	                                          n->BitCountOrDie()));
1300	      if (!is_signed) {
1301	        XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(nonnegative_result));
1302	        return true;
1303	      }
1304	
1305	      // By XLS convention, the sign of the modulus matches the sign of the LHS,
1306	      // so we should subtract the RHS from our result to get the negative
1307	      // remainder iff the LHS is negative and the result would otherwise be
1308	      // positive.
1309	      XLS_ASSIGN_OR_RETURN(
1310	          Node * truncated_zero,
1311	          n->function_base()->MakeNode<Literal>(
1312	              n->loc(), Value(UBits(0, truncated_lhs->BitCountOrDie()))));
1313	      XLS_ASSIGN_OR_RETURN(
1314	          Node * result_is_positive,
1315	          n->function_base()->MakeNode<CompareOp>(n->loc(), truncated_lhs,
1316	                                                  truncated_zero, Op::kNe));
1317	      XLS_ASSIGN_OR_RETURN(
1318	          Node * dividend_is_negative,
1319	          n->function_base()->MakeNode<BitSlice>(
1320	              n->loc(), n->operand(0),
1321	              /*start=*/n->operand(0)->BitCountOrDie() - 1, /*width=*/1));
1322	      XLS_ASSIGN_OR_RETURN(
1323	          Node * negative_result,
1324	          n->function_base()->MakeNode<BinOp>(n->loc(), nonnegative_result,
1325	                                              n->operand(1), Op::kSub));
1326	      XLS_ASSIGN_OR_RETURN(
1327	          Node * use_negative_result,
1328	          n->function_base()->MakeNode<NaryOp>(
1329	              n->loc(),
1330	              std::vector<Node*>({result_is_positive, dividend_is_negative}),
1331	              Op::kAnd));
1332	      XLS_RETURN_IF_ERROR(
1333	          n->ReplaceUsesWithNew<Select>(
1334	               use_negative_result,
1335	               std::vector<Node*>({nonnegative_result, negative_result}),
1336	               /*default_value=*/std::nullopt)
1337	              .status());
1338	      return true;
1339	    }
1340	
1341	    // Convert UMod/SMod by any other literal into a divide, multiply, and
1342	    // subtract; we'll later simplify the divide into a multiply & shift(s).
1343	    // (See MatchUnsignedDivide for how.)
1344	    XLS_ASSIGN_OR_RETURN(Node * quotient,
1345	                         n->function_base()->MakeNode<BinOp>(
1346	                             n->loc(), n->operand(0), n->operand(1),
1347	                             is_signed ? Op::kSDiv : Op::kUDiv));
1348	    XLS_ASSIGN_OR_RETURN(Node * approximant,
1349	                         n->function_base()->MakeNode<ArithOp>(
1350	                             n->loc(), quotient, n->operand(1),
1351	                             /*width=*/n->operand(0)->BitCountOrDie(),
1352	                             is_signed ? Op::kSMul : Op::kUMul));
1353	    XLS_RETURN_IF_ERROR(
1354	        n->ReplaceUsesWithNew<BinOp>(n->operand(0), approximant, Op::kSub)
1355	            .status());
1356	    return true;
1357	  }
1358	
1359	  // Convert UMod/SMod of a small constant (e.g., 13 % x) into a divide,
1360	  // multiply, and subtract; we'll later simplify the divide into a lookup
1361	  // table. (See MatchUnsignedDivide for how.)
1362	  if (n->OpIn({Op::kUMod, Op::kSMod}) &&
1363	      query_engine.IsFullyKnown(n->operand(0))) {
1364	    Bits dividend = *query_engine.KnownValueAsBits(n->operand(0));
1365	    if (dividend.IsZero()) {
1366	      // 0 % x == 0, for all x.
1367	      VLOG(2) << "FOUND: UMod/SMod of zero";
1368	      XLS_RETURN_IF_ERROR(
1369	          n->ReplaceUsesWithNew<Literal>(ZeroOfType(n->GetType())).status());
1370	      return true;
1371	    } else if (bits_ops::ULessThanOrEqual(bits_ops::Abs(dividend),
1372	                                          kMaxDividendForCompressedLUT)) {
1373	      VLOG(2) << "FOUND: UMod/SMod of small constant " << dividend
1374	              << "; replacing with remainder computation";
1375	      const bool is_signed = n->op() == Op::kSMod;
1376	      XLS_ASSIGN_OR_RETURN(Node * quotient,
1377	                           n->function_base()->MakeNode<BinOp>(
1378	                               n->loc(), n->operand(0), n->operand(1),
1379	                               is_signed ? Op::kSDiv : Op::kUDiv));
1380	      XLS_ASSIGN_OR_RETURN(Node * approximant,
1381	                           n->function_base()->MakeNode<ArithOp>(
1382	                               n->loc(), quotient, n->operand(1),
1383	                               /*width=*/n->operand(0)->BitCountOrDie(),
1384	                               is_signed ? Op::kSMul : Op::kUMul));
1385	      XLS_ASSIGN_OR_RETURN(Node * remainder,
1386	                           n->function_base()->MakeNode<BinOp>(
1387	                               n->loc(), n->operand(0), approximant, Op::kSub));
1388	      XLS_ASSIGN_OR_RETURN(Node * divisor_is_zero,
1389	                           CompareLiteral(n->operand(1), 0, Op::kEq));
1390	      XLS_ASSIGN_OR_RETURN(Node * zero,
1391	                           n->function_base()->MakeNode<Literal>(
1392	                               n->loc(), Value(UBits(0, n->BitCountOrDie()))));
1393	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<PrioritySelect>(
1394	                               divisor_is_zero,
1395	                               /*cases=*/absl::MakeConstSpan({zero}),
1396	                               /*default_value=*/remainder)
1397	                              .status());
1398	      return true;
1399	    }
1400	  }
1401	
1402	  XLS_ASSIGN_OR_RETURN(bool udiv_matched,
1403	                       MatchUnsignedDivideByConstant(n, query_engine));
1404	  if (udiv_matched) {
1405	    return true;
1406	  }
1407	
1408	  XLS_ASSIGN_OR_RETURN(bool sdiv_matched,
1409	                       MatchSignedDivideByConstant(n, query_engine));
1410	  if (sdiv_matched) {
1411	    return true;
1412	  }
1413	
1414	  // Pattern: UDiv/SDiv by a variable power of two (2^L << K).
1415	  XLS_ASSIGN_OR_RETURN(bool div_by_variable_power_of_two_matched,
1416	                       MatchDivByVariablePowerOfTwo(n, query_engine));
1417	  if (div_by_variable_power_of_two_matched) {
1418	    return true;
1419	  }
1420	
1421	  // Pattern: UDiv/SDiv of `X` by `Y << K` -> `(X / Y) / (1 << K)`
1422	  // This matches division by a shifted value (as long as the shift won't cause
1423	  // overflow or wraparound), breaking it into a division by `Y` and a division
1424	  // by `1 << K`. We'll later come back and simplify the division by `1 << K`,
1425	  // and other optimizations may later simplify the division by `Y` (especially
1426	  // if `Y` is a constant).
1427	  //
1428	  // Note on division by zero semantics:
1429	  // - For UDiv: UDiv by zero always returns the all-ones value.
1430	  // - For SDiv: SDiv by zero returns either MaxPos or MinNeg depending on the
1431	  //             sign of the dividend. Since the intermediate `X / Y` can invert
1432	  //             the sign of the dividend (if Y is negative) before hitting the
1433	  //             outer division by zero, we take this into account.
1434	  if (n->op() == Op::kUDiv || n->op() == Op::kSDiv) {
1435	    Node* divisor = n->operand(1);
1436	    if (divisor->op() == Op::kShll) {
1437	      Node* y = divisor->operand(0);
1438	      Node* k = divisor->operand(1);
1439	
1440	      const int64_t leading_zeros =
1441	          query_engine.KnownLeadingZeros(y).value_or(0);
1442	      const int64_t max_shift =
1443	          query_engine.MaxUnsignedValue(k).FitsInInt64Unsigned()
1444	              ? query_engine.MaxUnsignedValue(k).ToInt64().value()
1445	              : n->BitCountOrDie();
1446	      const int64_t limit = leading_zeros - ((n->op() == Op::kSDiv) ? 1 : 0);
1447	      if (max_shift <= limit) {
1448	        FunctionBase* f = n->function_base();
1449	        XLS_ASSIGN_OR_RETURN(
1450	            Node * new_dividend,
1451	            f->MakeNode<BinOp>(n->loc(), n->operand(0), y, n->op()));
1452	        XLS_ASSIGN_OR_RETURN(
1453	            Node * one, f->MakeNode<Literal>(
1454	                            n->loc(), Value(UBits(1, n->BitCountOrDie()))));
1455	        XLS_ASSIGN_OR_RETURN(Node * new_divisor,
1456	                             f->MakeNode<BinOp>(n->loc(), one, k, Op::kShll));
1457	        XLS_ASSIGN_OR_RETURN(
1458	            Node * div_by_shift_result,
1459	            f->MakeNode<BinOp>(n->loc(), new_dividend, new_divisor, n->op()));
1460	        Node* replacement;
1461	        if (!query_engine.Covers(divisor, UBits(0, divisor->BitCountOrDie()))) {
1462	          replacement = div_by_shift_result;
1463	        } else {
1464	          XLS_ASSIGN_OR_RETURN(Node * divisor_is_zero,
1465	                               CompareLiteral(divisor, 0, Op::kEq));
1466	          Node* div_by_zero_result;
1467	          if (n->op() == Op::kUDiv) {
1468	            XLS_ASSIGN_OR_RETURN(
1469	                div_by_zero_result,
1470	                f->MakeNode<Literal>(n->loc(),
1471	                                     Value(Bits::AllOnes(n->BitCountOrDie()))));
1472	          } else {
1473	            XLS_ASSIGN_OR_RETURN(
1474	                Node * min_neg_lit,
1475	                f->MakeNode<Literal>(
1476	                    n->loc(), Value(Bits::MinSigned(n->BitCountOrDie()))));
1477	            XLS_ASSIGN_OR_RETURN(
1478	                Node * max_pos_lit,
1479	                f->MakeNode<Literal>(
1480	                    n->loc(), Value(Bits::MaxSigned(n->BitCountOrDie()))));
1481	            XLS_ASSIGN_OR_RETURN(
1482	                Node * msb,
1483	                f->MakeNode<BitSlice>(n->loc(), n->operand(0),
1484	                                      n->operand(0)->BitCountOrDie() - 1, 1));
1485	            XLS_ASSIGN_OR_RETURN(
1486	                div_by_zero_result,
1487	                f->MakeNode<Select>(
1488	                    n->loc(), msb, std::vector<Node*>{max_pos_lit, min_neg_lit},
1489	                    std::nullopt));
1490	          }
1491	          XLS_ASSIGN_OR_RETURN(
1492	              replacement,
1493	              f->MakeNode<Select>(
1494	                  n->loc(), divisor_is_zero,
1495	                  std::vector<Node*>{div_by_shift_result, div_by_zero_result},
1496	                  std::nullopt));
1497	        }
1498	        XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(replacement));
1499	        return true;
1500	      }
1501	    }
1502	  }
1503	
1504	  // Logical shift by a constant can be replaced by a slice and concat.
1505	  //    (val << lit) -> Concat(BitSlice(val, ...), UBits(0, ...))
1506	  //    (val >> lit) -> Concat(UBits(0, ...), BitSlice(val, ...))
1507	  // If the shift amount is greater than or equal to the bit width the
1508	  // expression can be replaced with zero.
1509	  //
1510	  // This simplification is desirable as in the canonical lower-level IR a shift
1511	  // implies a barrel shifter which is not necessary for a shift by a constant
1512	  // amount.
1513	  if ((n->op() == Op::kShll || n->op() == Op::kShrl) &&
1514	      query_engine.IsFullyKnown(n->operand(1))) {
1515	    int64_t bit_count = n->BitCountOrDie();
1516	    const Bits shift_bits = *query_engine.KnownValueAsBits(n->operand(1));
1517	    if (shift_bits.IsZero()) {
1518	      // A shift by zero is a nop.
1519	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(n->operand(0)));
1520	      return true;
1521	    }
1522	    if (bits_ops::UGreaterThanOrEqual(shift_bits, bit_count)) {
1523	      // Replace with zero.
1524	      XLS_RETURN_IF_ERROR(
1525	          n->ReplaceUsesWithNew<Literal>(Value(UBits(0, bit_count))).status());
1526	      return true;
1527	    }
1528	    XLS_ASSIGN_OR_RETURN(uint64_t shift_amount, shift_bits.ToUint64());
1529	    XLS_ASSIGN_OR_RETURN(Node * zero,
1530	                         n->function_base()->MakeNode<Literal>(
1531	                             n->loc(), Value(UBits(0, shift_amount))));
1532	    int64_t slice_start = (n->op() == Op::kShll) ? 0 : shift_amount;
1533	    int64_t slice_width = bit_count - shift_amount;
1534	    XLS_ASSIGN_OR_RETURN(
1535	        Node * slice, n->function_base()->MakeNode<BitSlice>(
1536	                          n->loc(), n->operand(0), slice_start, slice_width));
1537	    auto concat_operands = (n->op() == Op::kShll)
1538	                               ? std::vector<Node*>{slice, zero}
1539	                               : std::vector<Node*>{zero, slice};
1540	    VLOG(2) << "FOUND: logical shift by constant";
1541	    XLS_RETURN_IF_ERROR(
1542	        n->ReplaceUsesWithNew<Concat>(concat_operands).status());
1543	    return true;
1544	  }
1545	
1546	  // Ext(Ext(x, w_0), w_1) => Ext(x, w_1)
1547	  if (n->Is<ExtendOp>() && n->op() == n->operand(0)->op()) {
1548	    VLOG(2) << "FOUND: replace extend(extend(x)) with extend(x)";
1549	    XLS_RETURN_IF_ERROR(
1550	        n->ReplaceUsesWithNew<ExtendOp>(n->operand(0)->operand(0),
1551	                                        n->BitCountOrDie(), n->op())
1552	            .status());
1553	    return true;
1554	  }
1555	
1556	  // An arithmetic shift right by a constant can be replaced by sign-extended
1557	  // slice of the to-shift operand.
1558	  //
1559	  //    (val >>> lit) -> sign_extend(BitSlice(val, ...))
1560	  //
1561	  // This simplification is desirable because in the canonical lower-level IR a
1562	  // shift implies a barrel shifter which is not necessary for a shift by a
1563	  // constant amount.
1564	  if (n->op() == Op::kShra && query_engine.IsFullyKnown(n->operand(1))) {
1565	    const int64_t bit_count = n->BitCountOrDie();
1566	    const Bits shift_bits = *query_engine.KnownValueAsBits(n->operand(1));
1567	    if (shift_bits.IsZero()) {
1568	      // A shift by zero is a nop.
1569	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(n->operand(0)));
1570	      return true;
1571	    }
1572	    int64_t slice_width;
1573	    if (bits_ops::UGreaterThanOrEqual(shift_bits, bit_count)) {
1574	      slice_width = 1;
1575	    } else {
1576	      XLS_ASSIGN_OR_RETURN(uint64_t shift_amount, shift_bits.ToUint64());
1577	      slice_width = bit_count - shift_amount;
1578	    }
1579	    XLS_ASSIGN_OR_RETURN(Node * slice, n->function_base()->MakeNode<BitSlice>(
1580	                                           n->loc(), n->operand(0),
1581	                                           /*start=*/bit_count - slice_width,
1582	                                           /*width=*/slice_width));
1583	    VLOG(2) << "FOUND: replace ashr by constant with signext(slice(x))";
1584	    XLS_RETURN_IF_ERROR(
1585	        n->ReplaceUsesWithNew<ExtendOp>(slice, bit_count, Op::kSignExt)
1586	            .status());
1587	    return true;
1588	  }
1589	
1590	  // Logical shift of a 1-bit value:
1591	  //   shll(y:bits[1], amt) == y & (amt == 0)
1592	  //   shrl(y:bits[1], amt) == y & (amt == 0)
1593	  //
1594	  // A 1-bit logical shift by a nonzero amount produces zero, and a shift by
1595	  // zero is a no-op.
1596	  if ((n->op() == Op::kShll || n->op() == Op::kShrl) &&
1597	      n->operand(0)->BitCountOrDie() == 1) {
1598	    VLOG(2) << "FOUND: logical shift of 1-bit value";
1599	    XLS_ASSIGN_OR_RETURN(Node * amt_is_zero,
1600	                         CompareLiteral(n->operand(1), 0, Op::kEq));
1601	    std::vector<Node*> args = {n->operand(0), amt_is_zero};
1602	    XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<NaryOp>(args, Op::kAnd).status());
1603	    return true;
1604	  }
1605	
1606	  // An arithmetic shift-right of a 1-bit value is a no-op.
1607	  if (n->op() == Op::kShra && n->operand(0)->BitCountOrDie() == 1) {
1608	    VLOG(2) << "FOUND: arithmetic shift-right of 1-bit value";
1609	    XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(n->operand(0)));
1610	    return true;
1611	  }
1612	
1613	  // Any shift right of a constant 1 can be replaced by a test for equality with
1614	  // zero (followed by a zero extension), since
1615	  //
1616	  //   (1 >> x) = 1 if x == 0,
1617	  //              0 otherwise.
1618	  //
1619	  // ... as long as it's not an arithmetic shift-right of bits[1]:1.
1620	  auto is_unsigned_one = [&](Node* node) {
1621	    const std::optional<Value> value = query_engine.KnownValue(node);
1622	    return value.has_value() && value->IsBits() && value->bits().IsOne();
1623	  };
1624	  if ((n->op() == Op::kShra || n->op() == Op::kShrl) &&
1625	      is_unsigned_one(n->operand(0))) {
1626	    // Make absolutely sure we're not dealing with an arithmetic shift-right of
1627	    // bits[1]:1. (For correctness, that case must be handled first.)
1628	    XLS_RET_CHECK(n->op() != Op::kShra || n->operand(0)->BitCountOrDie() > 1);
1629	
1630	    VLOG(2) << "FOUND: shift right of constant 1";
1631	    Node* x = n->operand(1);
1632	    XLS_ASSIGN_OR_RETURN(Literal * zero,
1633	                         n->function_base()->MakeNode<Literal>(
1634	                             n->loc(), Value(UBits(0, x->BitCountOrDie()))));
1635	    XLS_ASSIGN_OR_RETURN(Node * test, n->function_base()->MakeNode<CompareOp>(
1636	                                          n->loc(), x, zero, Op::kEq));
1637	    if (n->BitCountOrDie() == 1) {
1638	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(test));
1639	    } else {
1640	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<ExtendOp>(
1641	                               test, n->BitCountOrDie(), Op::kZeroExt)
1642	                              .status());
1643	    }
1644	    return true;
1645	  }
1646	
1647	  // A 1-wide decode can be simplified to a test for equality with zero; any
1648	  // other index results in zero output.
1649	  if (n->op() == Op::kDecode && n->BitCountOrDie() == 1) {
1650	    VLOG(2) << "FOUND: 1-wide decode";
1651	    XLS_ASSIGN_OR_RETURN(
1652	        Literal * zero,
1653	        n->function_base()->MakeNode<Literal>(
1654	            n->loc(), Value(UBits(0, n->operand(0)->BitCountOrDie()))));
1655	    XLS_RETURN_IF_ERROR(
1656	        n->ReplaceUsesWithNew<CompareOp>(n->operand(0), zero, Op::kEq)
1657	            .status());
1658	    return true;
1659	  }
1660	
1661	  // A 2-wide decode with a 1-bit operand can be simplified to:
1662	  //   decode(operand:u1) => concat(operand, not(operand)).
1663	  // 1-wide decodes should be handled above, and no wider decode is allowed for
1664	  // a 1-bit operand.
1665	  if (n->op() == Op::kDecode && n->operand(0)->BitCountOrDie() == 1 &&
1666	      n->BitCountOrDie() == 2) {
1667	    VLOG(2) << "FOUND: decode of 1-bit operand";
1668	    XLS_ASSIGN_OR_RETURN(
1669	        Node * not_operand,
1670	        n->function_base()->MakeNode<UnOp>(n->loc(), n->operand(0), Op::kNot));
1671	    XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<Concat>(
1672	                             std::vector<Node*>({n->operand(0), not_operand}))
1673	                            .status());
1674	    return true;
1675	  }
1676	
1677	  // We can eliminate negations that are only used in signed comparisons to
1678	  // literals or other negations, at minimal cost.
1679	  //
1680	  // NOTE: This is expected to reduce delay in other scenarios too, but we
1681	  //       currently have no way to model the tradeoff between area & delay, so
1682	  //       we only do this where we can fully eliminate one negation.
1683	  auto is_removable_negate = [&query_engine](Node* node) {
1684	    return node->op() == Op::kNeg &&
1685	           !node->function_base()->HasImplicitUse(node) &&
1686	           absl::c_all_of(node->users(), [&query_engine](Node* user) {
1687	             return IsSignedCompare(user) &&
1688	                    user->operand(0)->op() == Op::kNeg &&
1689	                    (query_engine.IsFullyKnown(user->operand(1)) ||
1690	                     user->operand(1)->op() == Op::kNeg);
1691	           });
1692	  };
1693	
1694	  // Pattern: Signed comparison of negated operands
1695	  //   eq(-lhs, -rhs)  =>  eq(lhs, rhs)
1696	  //   ne(-lhs, -rhs)  =>  ne(lhs, rhs)
1697	  //    (-lhs < -rhs)  =>  (lhs > rhs) XOR (lhs != MIN) XOR (rhs != MIN)
1698	  //    (-lhs > -rhs)  =>  (lhs < rhs) XOR (lhs != MIN) XOR (rhs != MIN)
1699	  //   (-lhs <= -rhs)  =>  (lhs >= rhs) XOR (lhs != MIN) XOR (rhs != MIN)
1700	  //   (-lhs >= -rhs)  =>  (lhs <= rhs) XOR (lhs != MIN) XOR (rhs != MIN)
