1702	      n->operand(0)->op() == Op::kNeg && n->operand(1)->op() == Op::kNeg &&
1703	      (is_removable_negate(n->operand(0)) ||
1704	       is_removable_negate(n->operand(1)))) {
1705	    VLOG(2) << "FOUND: Signed comparison of negated operands with no other use";
1706	    Node* lhs = n->operand(0)->operand(0);
1707	    Node* rhs = n->operand(1)->operand(0);
