1709	    Node* equivalent;
1710	    XLS_ASSIGN_OR_RETURN(Op reversed_op, ReverseComparisonOp(n->op()));
1711	    XLS_ASSIGN_OR_RETURN(Node * reversed_cmp,
1712	                         n->function_base()->MakeNode<CompareOp>(
1713	                             n->loc(), lhs, rhs, reversed_op));
