1715	      equivalent = reversed_cmp;
1716	    } else {
1717	      XLS_RET_CHECK_EQ(n->operand(0)->BitCountOrDie(),
1718	                       n->operand(1)->BitCountOrDie());
1719	      const int64_t bit_count = n->operand(0)->BitCountOrDie();
1720	      InlineBitmap hi_bit(bit_count);
1721	      hi_bit.Set(bit_count - 1);
1722	      XLS_ASSIGN_OR_RETURN(
1723	          Literal * min_value,
1724	          n->function_base()->MakeNode<Literal>(
1725	              n->loc(), Value(Bits::FromBitmap(std::move(hi_bit)))));
1726	      XLS_ASSIGN_OR_RETURN(Node * lhs_not_min,
1727	                           n->function_base()->MakeNode<CompareOp>(
1728	                               n->loc(), lhs, min_value, Op::kNe));
1729	      XLS_ASSIGN_OR_RETURN(Node * rhs_not_min,
1730	                           n->function_base()->MakeNode<CompareOp>(
1731	                               n->loc(), rhs, min_value, Op::kNe));
1732	      XLS_ASSIGN_OR_RETURN(
1733	          equivalent,
1734	          n->function_base()->MakeNode<NaryOp>(
1735	              n->loc(),
1736	              std::vector<Node*>{reversed_cmp, lhs_not_min, rhs_not_min},
1737	              Op::kXor));
1738	    }
