1744	  // Pattern: Signed comparison of negation to literal
1745	  //   eq(-expr, K)  =>  eq(expr, -K)
1746	  //   ne(-expr, K)  =>  ne(expr, -K)
1747	  //    (-expr < K)  =>  (expr > -K) XOR (expr != MIN) XOR (K != MIN)
1748	  //    (-expr > K)  =>  (expr < -K) XOR (expr != MIN) XOR (K != MIN)
1749	  //   (-expr <= K)  =>  (expr >= -K) XOR (expr != MIN) XOR (K != MIN)
1750	  //   (-expr >= K)  =>  (expr <= -K) XOR (expr != MIN) XOR (K != MIN)
1751	  //
1752	  // Canonicalization puts the literal on the right for comparisons.
1753	  if (IsBitsCompare(n) && IsSignedCompare(n) &&
1754	      n->operand(0)->op() == Op::kNeg &&
1755	      query_engine.IsFullyKnown(n->operand(1)) &&
1756	      is_removable_negate(n->operand(0))) {
1757	    VLOG(2) << "FOUND: Signed comparison of negation to literal";
1758	    Node* expr = n->operand(0)->operand(0);
1759	    Bits k_bits = *query_engine.KnownValueAsBits(n->operand(1));
1760	
1761	    Bits neg_k_bits = bits_ops::Negate(k_bits);
1762	    XLS_ASSIGN_OR_RETURN(Literal * neg_k,
1763	                         n->function_base()->MakeNode<Literal>(
1764	                             n->operand(1)->loc(), Value(neg_k_bits)));
1765	
1766	    Node* equivalent;
1767	    XLS_ASSIGN_OR_RETURN(Op reversed_op, ReverseComparisonOp(n->op()));
1768	    XLS_ASSIGN_OR_RETURN(Node * reversed_cmp,
1769	                         n->function_base()->MakeNode<CompareOp>(
1770	                             n->loc(), expr, neg_k, reversed_op));
1771	    if (n->op() == Op::kEq || n->op() == Op::kNe) {
1772	      equivalent = reversed_cmp;
1773	    } else {
1774	      XLS_RET_CHECK_EQ(n->operand(0)->BitCountOrDie(), k_bits.bit_count());
1775	      const int64_t bit_count = n->operand(0)->BitCountOrDie();
1776	      InlineBitmap hi_bit(bit_count);
1777	      hi_bit.Set(bit_count - 1);
1778	      Bits min_value_bits = Bits::FromBitmap(std::move(hi_bit));
1779	
1780	      Node* x;  // x := (expr != MIN) XOR (K != MIN)...
1781	                // but since k is known at compile time, we fold the answer in.
1782	      XLS_ASSIGN_OR_RETURN(Literal * min_value,
1783	                           n->function_base()->MakeNode<Literal>(
1784	                               n->loc(), Value(min_value_bits)));
