1787	                                    n->loc(), expr, min_value, Op::kEq));
1788	      } else {
1789	        XLS_ASSIGN_OR_RETURN(x, n->function_base()->MakeNode<CompareOp>(
1790	                                    n->loc(), expr, min_value, Op::kNe));
1791	      }
1792	      XLS_ASSIGN_OR_RETURN(
1793	          equivalent,
1794	          n->function_base()->MakeNode<NaryOp>(
1795	              n->loc(), std::vector<Node*>{reversed_cmp, x}, Op::kXor));
1796	    }
