1802	  // Shift amounts from the front-end are often unnecessarily zero
1803	  // extended. Strip the zero-extension (canonicalized to concat with zero):
1804	  //
1805	  //   a << {0, b} => a << b
1806	  if (n->op() == Op::kShll || n->op() == Op::kShrl || n->op() == Op::kShra) {
