1808	      Concat* concat = n->operand(1)->As<Concat>();
1809	      if (query_engine.IsAllZeros(concat->operand(0))) {
1810	        Node* new_shift_amount;
1811	        if (concat->operand_count() == 1) {
1812	          new_shift_amount = concat->operand(0);
1813	        } else if (concat->operand_count() == 2) {
1814	          new_shift_amount = concat->operand(1);
1815	        } else {
1816	          XLS_ASSIGN_OR_RETURN(
1817	              new_shift_amount,
1818	              n->function_base()->MakeNode<Concat>(
1819	                  concat->loc(), concat->operands().subspan(1)));
1820	        }
1821	        VLOG(2) << "FOUND: Removal of zero_ext of shift amount";
1822	        XLS_RETURN_IF_ERROR(n->ReplaceOperandNumber(1, new_shift_amount,
1823	                                                    /*type_must_match=*/false));
1824	        return true;
1825	      }
1826	    }
1827	  }
1828	  // This also applies to decode, though we may need to zero-extend the result
1829	  // if the argument gets too small.
1830	  //
1831	  //   decode({0, b}) => zero_ext(decode(b))
1832	  if (n->op() == Op::kDecode && n->operand(0)->Is<Concat>() &&
1833	      query_engine.IsAllZeros(n->operand(0)->As<Concat>()->operand(0))) {
1834	    Concat* concat = n->operand(0)->As<Concat>();
1835	    Node* new_index;
1836	    if (concat->operand_count() == 1) {
1837	      new_index = concat->operand(0);
1838	    } else if (concat->operand_count() == 2) {
1839	      new_index = concat->operand(1);
1840	    } else {
1841	      XLS_ASSIGN_OR_RETURN(new_index,
1842	                           n->function_base()->MakeNode<Concat>(
1843	                               concat->loc(), concat->operands().subspan(1)));
1844	    }
1845	    VLOG(2) << "FOUND: Removal of zero_ext of decode index";
1846	
1847	    int64_t n_width = n->BitCountOrDie();
1848	    int64_t operand_width = new_index->BitCountOrDie();
1849	
1850	    int64_t decode_width = n_width;
1851	    if (operand_width < 63) {
