1855	    }
1856	    XLS_ASSIGN_OR_RETURN(Node * decoded,
1857	                         n->function_base()->MakeNode<Decode>(
1858	                             n->loc(), new_index, decode_width));
1859	    XLS_ASSIGN_OR_RETURN(
1860	        decoded, NarrowOrExtend(decoded, /*n_is_signed=*/false, n_width));
