1865	  // Guards to prevent overshifting can be removed:
1866	  //
1867	  //   shift(x, clamp(amt, LIMIT))  =>  shift(x, amt) if LIMIT >= width(x)
1868	  //
1869	  // Where clamp(amt, LIMIT) is Sel(UGt(x, LIMIT), [x, LIMIT]).
1870	  // This is legal because the following identity holds:
1871	  //
1872	  //   shift(x, K) = shift(x, width(x)) for all K >= width(x).
1873	  //
1874	  // This transformation can be performed for any value of LIMIT greater than
1875	  // or equal to width(x).
1876	  if (n->op() == Op::kShll || n->op() == Op::kShrl || n->op() == Op::kShra) {
1877	    std::optional<ClampExpr> clamp_expr =
1878	        MatchClampUpperLimit(n->operand(1), query_engine);
1879	    if (clamp_expr.has_value() &&
1880	        bits_ops::UGreaterThanOrEqual(clamp_expr->upper_limit,
1881	                                      n->BitCountOrDie())) {
1882	      VLOG(2) << "FOUND: Removal of unnecessary shift guard";
1883	      XLS_RETURN_IF_ERROR(n->ReplaceOperandNumber(1, clamp_expr->node));
1884	      return true;
1885	    }
1886	  }
1887	  // This also applies to decode(clamp(amt, LIMIT)), since decode(x) == 1 << x.
1888	  if (n->op() == Op::kDecode) {
1889	    std::optional<ClampExpr> clamp_expr =
1890	        MatchClampUpperLimit(n->operand(0), query_engine);
1891	    if (clamp_expr.has_value() &&
1892	        bits_ops::UGreaterThanOrEqual(clamp_expr->upper_limit,
1893	                                      n->BitCountOrDie())) {
1894	      VLOG(2) << "FOUND: Removal of unnecessary decode guard";
