1905	                     [](Node* user) { return user->Is<BitSlice>(); })) {
1906	    int64_t width_used = 0;
1907	    for (Node* user : n->users()) {
1908	      BitSlice* slice = user->As<BitSlice>();
1909	      width_used = std::max(width_used, slice->start() + slice->width());
