1932	    for (Node* operand : n->operands()) {
1933	      if (operand->BitCountOrDie() == 0) {
1934	        VLOG(2) << "FOUND: replace " << OpToString(n->op())
1935	                << "(bits[0], ...) with 0";
1936	        XLS_RETURN_IF_ERROR(
1937	            n->ReplaceUsesWithNew<Literal>(ZeroOfType(n->GetType())).status());
1938	        return true;
1939	      }
1940	    }
1941	  }
