1943	  // SLt(x, 0) -> msb(x)
1944	  // SGe(x, 0) -> not(msb(x))
1945	  //
1946	  // Canonicalization puts the literal on the right for comparisons.
1947	  //
1948	  if (NarrowingEnabled(opt_level) && IsBitsCompare(n) &&
1949	      query_engine.IsAllZeros(n->operand(1))) {
1950	    if (n->op() == Op::kSLt) {
1951	      VLOG(2) << "FOUND: SLt(x, 0)";
1952	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<BitSlice>(
