1993	  //
1994	  //   x <= 0b0001111  =>  nor_reduce(msb_slice(x))
1995	  //   x >= 0b0001111  =>  or_reduce(msb_slice(x)) OR and_reduce(lsb_slice(x))
1996	  //
1997	  // Similarly:
1998	  //   (x > mask - 1)  <=>  (x >= mask)
1999	  auto get_mask_cmp =
2000	      [&](Node* node,
2001	          Op op) -> std::optional<std::tuple<Op, int64_t, int64_t>> {
2002	    const std::optional<Bits> constant = query_engine.KnownValueAsBits(node);
2003	    if (!constant.has_value()) {
2004	      return std::nullopt;
2005	    }
2006	    if (auto mask = LsbConstantMask(*constant); mask.has_value()) {
2007	      return std::make_tuple(op, mask->leading_zeros, mask->trailing_ones);
2008	    }
2009	    if (auto mask = LsbConstantMask(bits_ops::Increment(*constant));
2010	        mask.has_value() && op == Op::kUGt && !constant->IsAllOnes()) {
2011	      return std::make_tuple(Op::kUGe, mask->leading_zeros,
2012	                             mask->trailing_ones);
2013	    }
2014	    return std::nullopt;
2015	  };
