2017	  if (NarrowingEnabled(opt_level) && IsBitsCompare(n)) {
2018	    if (auto mask_cmp = get_mask_cmp(n->operand(1), n->op())) {
2019	      auto [effective_op, leading_zeros, trailing_ones] = *mask_cmp;
