2086	        decode_width = std::min(int64_t{1} << n_bit_count, decode_width);
2087	      }
2088	      XLS_ASSIGN_OR_RETURN(Node * decoded,
2089	                           n->function_base()->MakeNode<Decode>(
2090	                               n->loc(), n->operand(1), decode_width));
