2106	  // A common pattern for creating a mask with the N least-significant bits set
2107	  // is:
2108	  //   decode(N) - 1, or equivalently (1 << N) - 1.
2109	  // However, this can also be rewritten to:
2110	  //   !(all_ones << N),
2111	  // removing the adder. This is always beneficial, assuming the shift has no
2112	  // other uses.
2113	  auto get_decremented = [&](const Node* node) -> Node* {
2114	    if (node->op() == Op::kSub) {
2115	      if (std::optional<Bits> rhs =
2116	              query_engine.KnownValueAsBits(node->operand(1));
2117	          rhs.has_value() && rhs->IsOne()) {
2118	        return node->operand(0);
2119	      }
2120	      return nullptr;
2121	    }
2122	    if (node->op() != Op::kAdd) {
2123	      return nullptr;
2124	    }
2125	    if (query_engine.IsAllOnes(node->operand(1))) {
2126	      return node->operand(0);
2127	    }
2128	    if (query_engine.IsAllOnes(node->operand(0))) {
2129	      return node->operand(1);
2130	    }
2131	    return nullptr;
2132	  };
2133	  if (Node* decremented = get_decremented(n);
2134	      decremented != nullptr && decremented->op() == Op::kDecode) {
2135	    VLOG(2) << "FOUND: (decode(N)) - 1, replacing with !(all_ones << N)";
