2137	    Node* set_width = decremented->operand(0);
2138	    XLS_ASSIGN_OR_RETURN(Node * all_ones,
2139	                         n->function_base()->MakeNode<Literal>(
2140	                             n->loc(), Value(Bits::AllOnes(mask_width))));
2141	    XLS_ASSIGN_OR_RETURN(Node * inv_mask,
2142	                         n->function_base()->MakeNode<BinOp>(
2143	                             n->loc(), all_ones, set_width, Op::kShll));
2144	    XLS_RETURN_IF_ERROR(
2145	        n->ReplaceUsesWithNew<UnOp>(inv_mask, Op::kNot).status());
2146	    return true;
2147	  }
