2155	  // Pattern: Comparison of binary select between a value and its negation.
2156	  //
2157	  // This is a common shape for abs-like logic:
2158	  //   sel(pred, cases=[x, neg(x)]) == 0  =>  x == 0
2159	  //   sel(pred, cases=[x, neg(x)]) != 0  =>  x != 0
2160	  if (IsBitsCompare(n) && (n->op() == Op::kEq || n->op() == Op::kNe)) {
2161	    Node* selector_node = nullptr;
2162	    Node* zero_node = nullptr;
2163	    if (query_engine.IsAllZeros(n->operand(1))) {
2164	      selector_node = n->operand(0);
2165	      zero_node = n->operand(1);
2166	    } else if (query_engine.IsAllZeros(n->operand(0))) {
2167	      selector_node = n->operand(1);
2168	      zero_node = n->operand(0);
2169	    }
2170	    if (selector_node != nullptr && IsBinarySelectTwoCases(selector_node)) {
2171	      Select* sel = selector_node->As<Select>();
2172	      Node* case0 = sel->get_case(0);
2173	      Node* case1 = sel->get_case(1);
2174	      Node* x = nullptr;
2175	      if (case0->op() == Op::kNeg && case0->operand(0) == case1) {
2176	        x = case1;
2177	      } else if (case1->op() == Op::kNeg && case1->operand(0) == case0) {
2178	        x = case0;
2179	      }
2180	      if (x != nullptr) {
2181	        VLOG(2) << "FOUND: compare-to-zero of sel(x, neg(x))";
2182	        XLS_RETURN_IF_ERROR(
2183	            n->ReplaceUsesWithNew<CompareOp>(x, zero_node, n->op()).status());
2184	        return true;
2185	      }
2186	    }
2187	  }
2188	
2189	  // Pattern: Comparison of not (ones-complement negation) to literal
2190	  //   eq(~expr, K) => eq(expr, ~K)
2191	  //   ne(~expr, K) => ne(expr, ~K)
2192	  if (IsBitsCompare(n) && (n->op() == Op::kEq || n->op() == Op::kNe)) {
2193	    Node* not_node = nullptr;
2194	    Node* literal_node = nullptr;
2195	    if (n->operand(0)->op() == Op::kNot &&
2196	        query_engine.IsFullyKnown(n->operand(1))) {
2197	      not_node = n->operand(0);
2198	      literal_node = n->operand(1);
2199	    } else if (n->operand(1)->op() == Op::kNot &&
2200	               query_engine.IsFullyKnown(n->operand(0))) {
2201	      not_node = n->operand(1);
2202	      literal_node = n->operand(0);
2203	    }
2204	    if (not_node != nullptr) {
2205	      std::optional<Bits> k_bits = query_engine.KnownValueAsBits(literal_node);
2206	      XLS_RET_CHECK(k_bits.has_value());
2207	      XLS_RET_CHECK_EQ(k_bits->bit_count(), not_node->BitCountOrDie());
2208	      Bits not_k_bits = bits_ops::Not(*k_bits);
2209	      XLS_ASSIGN_OR_RETURN(Literal * not_k,
2210	                           n->function_base()->MakeNode<Literal>(
2211	                               literal_node->loc(), Value(not_k_bits)));
2212	      XLS_RETURN_IF_ERROR(
2213	          n->ReplaceUsesWithNew<CompareOp>(not_node->operand(0), not_k, n->op())
2214	              .status());
2215	      return true;
2216	    }
2217	  }
2218	
2219	  if ((n->OpIn({Op::kSMul, Op::kUMul})) &&
2220	      query_engine.IsFullyKnown(n->operand(1))) {
2221	    const Bits rhs = *query_engine.KnownValueAsBits(n->operand(1));
2222	    int64_t pop_count = rhs.PopCount();
2223	
2224	    if (pop_count == 0) {
2225	      XLS_RETURN_IF_ERROR(
2226	          n->ReplaceUsesWithNew<Literal>(ZeroOfType(n->GetType())).status());
2227	      return true;
2228	    }
2229	
2230	    // Position of the last leading zero
2231	    const int64_t llz = rhs.bit_count() - rhs.CountLeadingZeros();
2232	    const Bits rhs_complement = bits_ops::Sub(
2233	        llz < rhs.bit_count() ? Bits::PowerOfTwo(llz, rhs.bit_count())
2234	                              : Bits(rhs.bit_count()),
2235	        rhs);
2236	
2237	    const int64_t adders = pop_count - 1;
2238	    const int64_t complement_adders = rhs_complement.PopCount();
2239	
2240	    constexpr int64_t kAdderLimit = 1;
2241	
2242	    const bool is_signed = n->op() == Op::kSMul;
2243	    if (adders <= kAdderLimit && adders <= complement_adders &&
2244	        SplitsEnabled(opt_level) &&
2245	        (!is_signed || bits_ops::SGreaterThan(rhs, 0))) {
2246	      VLOG(2) << "FOUND: mul by positive literal with " << rhs.PopCount()
2247	              << " bits set (" << rhs.ToDebugString() << ")";
2248	      Node* result = nullptr;
2249	      XLS_ASSIGN_OR_RETURN(
2250	          Node * adjusted_lhs,
2251	          NarrowOrExtend(n->operand(0), is_signed, n->BitCountOrDie()));
2252	      for (int64_t i = 0; i < rhs.bit_count(); ++i) {
2253	        if (!rhs.Get(i)) {
2254	          continue;
2255	        }
2256	        Node* shifted_input;
2257	        if (i > 0) {
2258	          XLS_ASSIGN_OR_RETURN(Node * shift_amount,
2259	                               n->function_base()->MakeNode<Literal>(
2260	                                   n->loc(), Value(UBits(i, rhs.bit_count()))));
2261	          XLS_ASSIGN_OR_RETURN(
2262	              shifted_input,
2263	              n->function_base()->MakeNode<BinOp>(n->loc(), adjusted_lhs,
2264	                                                  shift_amount, Op::kShll));
2265	        } else {
2266	          shifted_input = adjusted_lhs;
2267	        }
2268	        if (result == nullptr) {
2269	          result = shifted_input;
2270	        } else {
2271	          XLS_ASSIGN_OR_RETURN(result,
2272	                               n->function_base()->MakeNode<BinOp>(
2273	                                   n->loc(), result, shifted_input, Op::kAdd));
2274	        }
2275	      }
2276	      CHECK_NE(result, nullptr);
2277	      XLS_RETURN_IF_ERROR(n->ReplaceUsesWith(result));
2278	      return true;
2279	    }
2280	
2281	    if (complement_adders <= kAdderLimit && SplitsEnabled(opt_level) &&
2282	        (!is_signed || bits_ops::SGreaterThan(rhs, 0))) {
2283	      VLOG(2) << "FOUND: mul by positive literal with "
2284	              << rhs_complement.PopCount() << " bit(s) set in its complement ("
2285	              << rhs_complement.ToDebugString() << ")";
2286	      // The RHS can be written as (1 << llz) - K, where K has fewer than
2287	      // kAdderLimit bits set.
2288	      XLS_ASSIGN_OR_RETURN(
2289	          Node * adjusted_lhs,
2290	          NarrowOrExtend(n->operand(0), is_signed, n->BitCountOrDie()));
2291	      XLS_ASSIGN_OR_RETURN(Node * large_shift_amount,
2292	                           n->function_base()->MakeNode<Literal>(
2293	                               n->loc(), Value(UBits(llz, rhs.bit_count()))));
2294	      XLS_ASSIGN_OR_RETURN(Node * base, n->function_base()->MakeNode<BinOp>(
2295	                                            n->loc(), adjusted_lhs,
2296	                                            large_shift_amount, Op::kShll));
2297	      Node* complement = nullptr;
2298	      for (int64_t i = 0; i < rhs_complement.bit_count(); ++i) {
2299	        if (!rhs_complement.Get(i)) {
2300	          continue;
2301	        }
2302	        XLS_ASSIGN_OR_RETURN(Node * shift_amount,
2303	                             n->function_base()->MakeNode<Literal>(
2304	                                 n->loc(), Value(UBits(i, rhs.bit_count()))));
2305	        XLS_ASSIGN_OR_RETURN(
2306	            Node * shifted_input,
2307	            n->function_base()->MakeNode<BinOp>(n->loc(), adjusted_lhs,
2308	                                                shift_amount, Op::kShll));
2309	        if (complement == nullptr) {
2310	          complement = shifted_input;
2311	        } else {
2312	          XLS_ASSIGN_OR_RETURN(
2313	              complement, n->function_base()->MakeNode<BinOp>(
2314	                              n->loc(), complement, shifted_input, Op::kAdd));
2315	        }
2316	      }
2317	      XLS_RETURN_IF_ERROR(
2318	          n->ReplaceUsesWithNew<BinOp>(base, complement, Op::kSub).status());
2319	      return true;
2320	    }
2321	  }
2322	
2323	  // Pattern: add(sign_ext(c: u1), K) => sel(c, [K, K-1])
2324	  // For a boolean 'c' sign-extended to N bits, sign_ext(c) is either 0 or all
2325	  // ones (-1). Simplify add(sign_ext(c), K) to select(c, [K, K-1]) for a
2326	  // bitwise op.
2327	  if (n->op() == Op::kAdd) {
2328	    Node* sign_ext = nullptr;
2329	    Node* const_node = nullptr;
2330	    if (n->operand(0)->op() == Op::kSignExt &&
2331	        n->operand(0)->As<ExtendOp>()->operand(0)->BitCountOrDie() == 1 &&
2332	        query_engine.IsFullyKnown(n->operand(1))) {
2333	      sign_ext = n->operand(0);
2334	      const_node = n->operand(1);
2335	    } else if (n->operand(1)->op() == Op::kSignExt &&
2336	               n->operand(1)->As<ExtendOp>()->operand(0)->BitCountOrDie() ==
2337	                   1 &&
2338	               query_engine.IsFullyKnown(n->operand(0))) {
2339	      sign_ext = n->operand(1);
2340	      const_node = n->operand(0);
2341	    }
2342	    if (sign_ext != nullptr) {
2343	      Bits k_bits = *query_engine.KnownValueAsBits(const_node);
2344	      int64_t width = n->BitCountOrDie();
2345	      if (k_bits.bit_count() == width) {
2346	        Bits k_minus_one = bits_ops::Sub(k_bits, UBits(1, width));
2347	        XLS_ASSIGN_OR_RETURN(
2348	            Literal * literal_k,
2349	            n->function_base()->MakeNode<Literal>(n->loc(), Value(k_bits)));
2350	        XLS_ASSIGN_OR_RETURN(Literal * literal_km1,
2351	                             n->function_base()->MakeNode<Literal>(
2352	                                 n->loc(), Value(k_minus_one)));
2353	        Node* cond = sign_ext->As<ExtendOp>()->operand(0);
2354	        XLS_RETURN_IF_ERROR(n->ReplaceUsesWithNew<Select>(
2355	                                 cond,
2356	                                 std::vector<Node*>({literal_k, literal_km1}),
2357	                                 /*default_value=*/std::nullopt)
2358	                                .status());
2359	        return true;
2360	      }
2361	    }
2362	  }
2363	
2364	  return false;
2365	}
2366	
2367	}  // namespace
2368	
2369	RedundancyGuard ArithSimplificationPass::GetRedundancyGuard(
2370	    const OptimizationPassOptions& options,
2371	    OptimizationContext& context) const {
2372	  return RedundancyGuard::CanSkip(absl::StrFormat("O%d", options.opt_level));
2373	}
2374	
2375	absl::StatusOr<bool> ArithSimplificationPass::RunOnFunctionBaseInternal(
2376	    FunctionBase* f, const OptimizationPassOptions& options,
2377	    PassResults* results, OptimizationContext& context) const {
2378	  bool changed = false;
2379	  bool pass_changed = false;
2380	  StatelessQueryEngine query_engine;
2381	  do {
2382	    pass_changed = false;
2383	    XLS_ASSIGN_OR_RETURN(std::vector<Node*> reverse_topo_sort_nodes,
2384	                         context.ReverseTopoSort(f));
2385	    for (Node* n : reverse_topo_sort_nodes) {
2386	      if (n->IsDead()) {
2387	        continue;
2388	      }
2389	      XLS_ASSIGN_OR_RETURN(
2390	          bool node_changed,
2391	          MatchArithPatterns(options.opt_level, n, query_engine));
2392	      if (node_changed) {
2393	        pass_changed = true;
2394	      }
2395	    }
2396	    changed |= pass_changed;
2397	  } while (pass_changed);
2398	  return changed;
2399	}
2400	
2401	}  // namespace xls
